"Посмотри видео от Барсика. Когда досмотришь, нажми «Дальше» — и тебя ждут задания.": "看巴尔西克的视频。看完后点击“下一步”,题目在等你。",
"Знакомимся с устройствами": "认识设备",
"Привет! Это Барсик. Сегодня мы познакомимся с компьютером. У компьютера есть разные устройства. Монитор, клавиатура, мышь, принтер, колонки, ноутбук, наушники и джойстик. Нажимай на каждое и узнавай, для чего оно нужно.": "你好!我是巴尔西克。今天我们来认识电脑。电脑有各种设备:显示器、键盘、鼠标、打印机、音箱、笔记本电脑、耳机和游戏手柄。点点每一个,了解它们有什么用。",
"Как называется устройство?": "这个设备叫什么?",
"Посмотри на картинку и выбери название устройства.": "看图片,选出设备的名称。",
"Найди устройство": "找出设备",
"Теперь наоборот. Прочитай название и найди нужную картинку.": "现在反过来。读名称,找出对应的图片。",
"Видео: Что делает устройство?": "视频:设备有什么用?",
"Угадай устройство": "猜一猜是什么设备",
"Я опишу устройство, а ты угадаешь, что это. Читай внимательно.": "我来描述设备,你来猜是什么。仔细读哦。",
"Управляем или смотрим?": "是操作还是观看?",
"Одними устройствами мы управляем: это клавиатура, мышь и джойстик. Другие показывают, печатают или звучат: монитор, принтер, колонки и наушники. Реши, к какой группе относится устройство.": "有些设备是用来控制的:键盘、鼠标和游戏手柄。另一些用来显示、打印或发声:显示器、打印机、音箱和耳机。判断设备属于哪一组。",
"Проверим себя": "检查一下自己",
"Повторим всё вместе: названия, описания и группы устройств.": "我们一起复习:设备的名称、描述和分组。",
"Видео: Правила работы": "视频:使用规则",
"Правила за компьютером": "电脑前的规则",
"За компьютером нужно вести себя правильно. Сиди прямо и не слишком близко к экрану. Делай перерывы, когда устали глаза. Не трогай розетки и провода. Никому не говори свой пароль. А если что-то напугало, позови взрослого. Нажимай на карточки и читай.": "在电脑前要守规矩。坐直,不要离屏幕太近。眼睛累了就休息。不要碰插座和电线。不要告诉任何人你的密码。如果有东西吓到你,就叫大人。点点卡片,读一读。",
"Правильно или нет?": "对还是不对?",
"Прочитай правило и скажи, правильно ли так делать.": "读规则,说说这样做对不对。",
"Проверим правила": "检查规则",
"Ещё раз проверим правила и устройства.": "再检查一遍规则和设备。",
"Видео: Порядок действий": "视频:行动顺序",
"Расставь шаги по порядку": "把步骤排好顺序",
"Компьютер умеет выполнять действия только по порядку, шаг за шагом. Такой порядок действий называют алгоритмом. Попробуй сам. Нажимай на шаги по порядку: что делаем сначала, что потом.": "电脑只会按顺序、一步一步地执行动作。这样的行动顺序叫算法。你自己试试。按顺序点击步骤:先做什么,后做什么。",
"Что делаем раньше?": "先做什么?",
"Ответь, что нужно сделать первым, последним, а что сразу после этого шага.": "回答:哪一步要先做,哪一步最后做,哪一步紧接在这一步之后。",
"Смешанные задания": "综合题",
"Последняя проверка курса. Устройства, правила и порядок действий.": "课程的最后检查。设备、规则和行动顺序。",
"Курс пройден!": "课程完成了!",
"Теперь ты знаешь устройства компьютера, правила безопасной работы и умеешь расставлять шаги по порядку. Дальше тренируйся в играх. Я буду рядом!": "现在你认识了电脑的设备、安全使用的规则,还会把步骤排好顺序。接下来在游戏里多练习。我会一直陪着你!",
