"Птицы улетают в тёплые края, где зимой есть корм.": "鸟儿飞到温暖的地方,那里冬天也有食物。",
"Делает запасы": "储存食物",
"Эти животные осенью собирают корм и прячут его на зиму.": "这些动物在秋天收集食物,把它藏起来过冬。",
