"Знание о погоде помогает одеться и подготовиться.": "了解天气有助于穿衣和做好准备。",
"Зачем знать правила обращения с электричеством?": "为什么要知道用电的规则?",
"Чтобы пользоваться приборами безопасно": "为了安全地使用电器",
"Электричество опасно, поэтому правила нужно знать.": "电很危险,所以要知道规则。",
