"На свету": "在光下",
"В темноте": "在黑暗中",
"Через три дня: на свету росток зелёный и сильный, в темноте — бледный и слабый.": "三天后:在光下的幼苗是绿色、强壮的,在黑暗中的是苍白、虚弱的。",
