"Растению не нужна вода": "植物不需要水",
"Растение боится окна": "植物怕窗户",
"Без света росток слабеет: растениям нужен свет.": "没有光,幼苗会变弱:植物需要光。",
"Лёд и тепло": "冰和温暖",
"Два кубика льда. Один положили на тёплое блюдце на солнце, другой оставили в морозилке.": "两块冰。一块放在阳光下温暖的小碟子上,另一块留在冰箱冷冻室里。",
"На солнце": "在阳光下",
"В морозилке": "在冷冻室里",
"Через несколько минут: на солнце лёд превратился в воду, в морозилке остался льдом.": "几分钟后:在阳光下冰变成了水,在冷冻室里仍然是冰。",
"Тепло растапливает лёд": "温暖使冰融化",
"Лёд сам решил растаять": "冰自己决定融化",
"Лёд любит морозилку": "冰喜欢冷冻室",
"От тепла лёд тает и становится водой.": "受热后冰会融化,变成水。",
"Тонет или плавает": "沉还是浮",
"Опустим в воду камешек и деревянную дощечку.": "我们把小石子和小木板放进水里。",
