"Ты сравнил животных и растения!": "你比较了动物和植物!",
"Природу изучают, чтобы заботиться о ней и жить безопасно!": "研究自然是为了爱护它、安全地生活!",
"Погода": "天气",
"Безопасность": "安全",
"Новое": "新知识",
"Видео: Зачем изучать природу": "视频:为什么要研究自然",
"Зачем людям изучать растения, животных и погоду? Нажимай на картинки и узнаешь.": "人们为什么要研究植物、动物和天气?点点图片你就知道了。",
"Зачем это нужно?": "为什么需要这个?",
"Выбери, зачем нужно знать то, о чём спрашивает вопрос.": "选出为什么要知道问题所问的内容。",
"Дневник погоды": "天气日记",
"Ты будешь настоящим исследователем. Четыре дня подряд смотри в окно и на термометр и записывай в дневник погоду и температуру.": "你要当一名真正的探究者。连续四天看窗外和温度计,把天气和温度记在日记里。",
"Как наблюдать": "怎样观察",
"Вспомни, как правильно проводить наблюдения.": "想一想怎样正确地进行观察。",
"Видео: Опыты и сравнения": "视频:实验和比较",
"Смотрим опыты": "看实验",
"Сейчас ты увидишь три опыта. Сначала посмотри, что мы приготовили. Потом нажми «Запустить опыт», увидь результат и объясни, почему так получилось.": "现在你会看到三个实验。先看看我们准备了什么。然后点“开始实验”,看结果,并解释为什么会这样。",
"Что получится?": "会发生什么?",
"Подумай, что получится в опыте, и выбери ответ.": "想一想实验会怎么样,选出答案。",
"Животные и растения": "动物和植物",
"Давай сравним животных и растения. Выбери, у кого есть этот признак: только у животных, только у растений или у обоих.": "我们来比较动物和植物。选出谁有这个特征:只有动物、只有植物,还是两者都有。",
"Сходства и различия": "相同和不同",
"Ответь на вопросы о том, чем похожи и чем отличаются животные и растения.": "回答关于动物和植物有什么相同、有什么不同的问题。",
"Последняя проверка: зачем изучать природу, наблюдения, опыты и сравнения.": "最后的检查:为什么研究自然、观察、实验和比较。",
"Теперь ты знаешь, зачем изучать природу, как проводить наблюдения, как объяснять опыты и сравнивать животных и растения. Дальше тренируйся в играх. Я буду рядом!": "现在你知道了为什么要研究自然、怎样观察、怎样解释实验以及怎样比较动物和植物。接下来在游戏里多练习。我会一直陪着你!",
