"Это тёплое или холодное?": "这个是暖的还是冷的?",
"Этот источник звука естественный или искусственный?": "这个声源是天然的还是人造的?",
"Притянет ли это магнит?": "磁铁会吸住这个吗?",
"притянется, потому что сделано из железа.": "会被吸住,因为它是铁做的。",
