"работает от электричества.": "靠电工作。",
"не работает от электричества.": "不靠电工作。",
"Так безопасно. С электричеством лучше быть осторожным и звать взрослых.": "这样是安全的。碰电最好小心,并叫大人帮忙。",
"Это очень опасно! Электричество может ударить током. Розетки и провода трогать нельзя.": "这非常危险!电会电人。插座和电线不能碰。",
"Это круглое, как Земля?": "这个像地球一样是圆的吗?",
"круглое, как Земля.": "像地球一样是圆的。",
"не круглое, а Земля круглая.": "不是圆的,而地球是圆的。",
"Изучать космос": "研究太空",
"Измерять время": "测量时间",
"Естественный свет даёт природа, искусственный — человек.": "天然光是大自然给的,人造光是人制造的。",
"Естественный источник света: его создала природа.": "天然光源:是大自然创造的。",
"Искусственный источник света: его сделал человек.": "人造光源:是人制造的。",
"Костёр, свеча и Солнце греют, а снег и лёд холодные.": "篝火、蜡烛和太阳会发热,雪和冰是冷的。",
"Это тёплое: оно греет, рядом с ним тепло.": "这个是暖的:它会发热,旁边很暖和。",
"Звуки есть в природе и есть звуки, которые делает человек.": "自然界有各种声音,也有人制造的声音。",
"Естественный источник звука: звук идёт от природы или животного.": "天然声源:声音来自大自然或动物。",
"Искусственный источник звука: его сделал человек.": "人造声源:是人制造的。",
"Помни: розетки и провода трогать нельзя!": "记住:插座和电线不能碰!",
"Работает от электричества. Но розетки и провода трогать нельзя — это опасно!": "靠电工作。但插座和电线不能碰——很危险!",
"Это не работает от электричества.": "这个不靠电工作。",
"Земля круглая, как мяч. Глобус — её модель.": "地球像球一样是圆的。地球仪是它的模型。",
"Глобус — это модель Земли. Земля круглая, как шар.": "地球仪是地球的模型。地球像球一样圆。",
"Круглое, как Земля.": "像地球一样是圆的。",
"Это не круглое, не похоже на Землю.": "这个不是圆的,不像地球。",
"Космос изучают приборами, а время измеряют часами и календарём.": "用仪器研究太空,用钟表和日历测量时间。",
"Этот прибор — для космоса.": "这个仪器是用于太空的。",
"Этот прибор — для времени.": "这个仪器是用于时间的。",
"Магнит притянул! Он сделан из железа.": "磁铁吸住了!它是铁做的。",
