"Держать в карманах": "放在口袋里",
"Руки согнуты в локтях и помогают бежать.": "手臂在肘部弯曲,帮助跑步。",
"Как держать равновесие на одной ноге?": "怎样单脚保持平衡?",
"Смотреть вперёд, руки в стороны": "看前方,手臂向两侧伸开",
