"Со спины": "从背后",
"Лёжа": "躺着",
"Замах и шаг вперёд помогают бросить точнее.": "摆臂和向前迈步能让投得更准。",
"Прыгать через скакалку трудно. Как сделать упражнение проще?": "跳绳很难。怎样让这个练习更容易?",
"Прыгать на месте, медленнее": "在原地跳,慢一点",
