"Не играть никогда": "永远不玩",
"Подбери инвентарь по силам.": "选和自己力气相配的器材。",
"Тебе трудно сделать упражнение. Что правильно?": "你觉得做这个练习很难。怎样做才对?",
"Сказать учителю и попробовать попроще": "告诉老师,先试试简单一点的",
