"Видео: Как мы двигаемся": "视频:我们怎样运动",
"Четыре свойства движения": "动作的四个特性",
"Можно двигаться быстро, как гепард, или медленно, как черепаха. Это скорость, то есть время движения.": "可以像猎豹一样快,也可以像乌龟一样慢。这是速度,也就是动作的时间。",
"Куда и где мы двигаемся: вперёд, назад, вбок, вверх и вниз, высоко и низко, широко и узко.": "我们向哪里、在哪里运动:向前、向后、向侧面、向上和向下、高和低、宽和窄。",
"Движение может быть лёгким, как у бабочки, или сильным и тяжёлым, как у слона. Это усилие.": "动作可以像蝴蝶那样轻,也可以像大象那样有力而沉重。这是力度。",
"Можно двигаться плавно, как волна, без остановок, а можно рывками, как робот.": "可以像波浪一样流畅、不停顿地运动,也可以像机器人一样一顿一顿地运动。",
"Любое движение можно описать по-разному. Оно бывает быстрым или медленным. Можно двигаться вперёд, назад, высоко и низко. Бывает лёгким или сильным. Плавным или резким. Нажимай на картинки и смотри, как это выглядит.": "任何动作都可以用不同的方式描述。它可以是快的或慢的。可以向前、向后、高高低低地运动。可以是轻的或有力的。可以是流畅的或突然的。点点图片,看看是什么样的。",
"Что меняется?": "什么在变?",
"Прочитай и скажи, что меняется в движении: время, пространство, вес или плавность.": "读一读,说说动作里什么在变:时间、空间、重量还是流畅度。",
"Видео: Что я умею": "视频:我会什么",
"Основные навыки": "基本技能",
"Корпус слегка наклонён вперёд, руки согнуты в локтях и помогают бежать.": "身体稍稍前倾,手臂在肘部弯曲,帮助跑步。",
"Оттолкнись ногами и приземлись мягко, на полусогнутые ноги.": "用脚蹬地,双腿微弯轻轻落地。",
"Равновесие": "平衡",
"Смотри вперёд на одну точку, руки в стороны. Так проще стоять на одной ноге.": "看着前面的一个点,手臂向两侧伸开。这样单脚站立更容易。",
"Бросок и ловля мяча": "投球和接球",
"Для броска сделай замах рукой и шаг вперёд. Ловя мяч, смотри на него и тяни руки навстречу.": "投球时先摆臂,再向前迈一步。接球时看着球,把手臂迎着球伸出去。",
"Есть основные двигательные навыки: бег, прыжок, равновесие, бросок и ловля мяча. Нажимай на картинки и запоминай, как их выполнять правильно.": "基本运动技能有:跑、跳、平衡、投球和接球。点点图片,记住怎样正确地做。",
"Выбери, как правильно выполнять движение.": "选出怎样正确地做这个动作。",
"Мои умения": "我的本领",
"Расскажи о себе: что у тебя уже получается, а чему ты учишься.": "说说你自己:你已经会什么,又在学什么。",
"Умею хорошо": "我做得好",
