"Расскажи о своих умениях. Что у тебя получается хорошо, а чему ты ещё учишься. Это не страшно: все чему-то учатся. Потом выбери, что хочешь улучшить.": "说说你的本领。你什么做得好,又在学什么。这没什么可怕的:大家都在学东西。然后选出你想改进的。",
"Как сказать о себе": "怎样说自己",
"Выбери, как честно и спокойно рассказать о своих умениях.": "选出怎样诚实而平静地说说自己的本领。",
"Трудности и риски": "困难和风险",
"Бывают трудности: скользкий пол, тяжёлый мяч, усталость. Подумай, как с ними справиться, и что делать, если больно.": "会遇到困难:地板滑、球太重、累了。想一想怎样应对,以及疼的时候该怎么办。",
"Видео: Где и как двигаться": "视频:在哪里、怎样运动",
