"Пол ровный. Можно бегать и играть в мяч, но держи дистанцию.": "地面平整。可以跑步、玩球,但要保持距离。",
"Площадка": "场地",
"Школьная площадка": "学校场地",
"Места много, но смотри под ноги и по сторонам. Не выбегай на дорогу.": "地方很大,但要看脚下和四周。不要跑到路上。",
