"Скользко. Шаги маленькие, не бегай.": "很滑。步子要小,不要跑。",
"Песок": "沙子",
"Ноги вязнут. Поднимай ноги выше и не спеши.": "脚会陷进去。把腿抬高,不要着急。",
"Коридор": "走廊",
"Узкое место": "狭窄的地方",
"В тесном месте идут шагом. Бегать и толкаться нельзя.": "在拥挤的地方要走路。不能跑、不能推人。",
"Двигаться можно в разных местах: в зале, на площадке, на льду, на песке, в коридоре. Везде действуют свои правила. Нажимай на картинки и запоминай.": "可以在不同的地方运动:体育馆里、场地上、冰上、沙子上、走廊里。每个地方都有自己的规则。点点图片,记住它们。",
"Как двигаться?": "怎样运动?",
"Выбери, как нужно двигаться в этом месте.": "选出在这个地方应该怎样运动。",
"Запомни и повтори": "记住并重复",
"Посмотри на комбинацию движений и запомни. Потом повтори её в том же порядке: нажимай на кнопки с движениями. Можно и сам делать эти движения!": "看看动作组合并记住。然后按同样的顺序重复:点按带动作的按钮。你也可以自己做这些动作!",
"Видео: Цели и планы": "视频:目标和计划",
