"План": "计划",
"Шаги, которые ведут к цели. Они идут по порядку.": "通向目标的步骤。它们是按顺序排列的。",
"Стратегия": "战术",
"Способ действовать, чтобы выиграть в игре. Например: передавать мяч друзьям и держаться вместе.": "在游戏中取胜的行动方式。比如:把球传给朋友,大家团结在一起。",
"Идея": "主意",
"Новая мысль: как двигаться или во что играть. Идеи можно придумывать самому.": "新的想法:怎样运动或玩什么。想法可以自己想出来。",
"Сам": "自己",
"Работаю сам": "我自己做",
"Чтобы достичь цели самому, нужно тренироваться понемногу каждый день и отмечать успехи.": "要自己达到目标,需要每天练习一点,并记录成绩。",
"Чтобы научиться новому, нужна цель. К цели ведёт план. В играх помогает стратегия. А идеи ты можешь придумывать сам. Нажимай на картинки.": "要学新东西,需要有目标。目标由计划通向。游戏中战术有帮助。想法你可以自己想出来。点点图片吧。",
"План: научиться прыгать": "计划:学会跳绳",
"Составь план, как научиться прыгать через скакалку двадцать раз.": "制定一个计划,怎样学会跳绳二十次。",
