"План готов!": "计划做好了!",
"Поставить цель: двадцать прыжков": "定目标:跳二十次",
"Считать прыжки и записывать": "数跳绳次数并记录",
"Порадоваться результату": "为成绩高兴",
"Составь план. Что нужно сделать сначала, а что потом, чтобы научиться прыгать через скакалку двадцать раз.": "制定一个计划。为了学会跳绳二十次,什么要先做,什么要后做。",
