"Поставь свою цель. Выбери, чему хочешь научиться, когда будешь тренироваться, как проверишь результат и кто тебе поможет.": "设定你的目标。选出你想学什么、什么时候练习、怎样检查成绩以及谁会帮你。",
"Ответь на вопросы о целях, планах и стратегиях.": "回答关于目标、计划和战术的问题。",
"Видео: Роли и творчество": "视频:角色和创意",
"Кто есть кто в игре": "游戏里谁是谁",
"Ведёт команду и подбадривает игроков.": "带领队伍,给队员鼓劲。",
"Выполняет задание в игре.": "在游戏里完成任务。",
"Следит, чтобы все соблюдали правила.": "监督大家遵守规则。",
"Готовит инвентарь: приносит мячи и обручи.": "准备器材:拿球和呼啦圈。",
"Поддерживает команду добрыми словами.": "用友善的话支持队伍。",
"В игре у каждого своя роль. Есть капитан, игрок, судья, помощник и болельщик. Все роли важны. Нажимай на картинки и запоминай.": "游戏里每个人都有自己的角色。有队长、选手、裁判、助手和球迷。所有角色都很重要。点点图片,记住它们。",
"Определи, какая роль в игре.": "判断这是游戏里的什么角色。",
"Делимся и договариваемся": "分享和商量",
"Как делить мяч, место и идеи, чтобы всем было хорошо?": "怎样分球、分场地、分想法,让大家都满意?",
