". Двигаемся:": "。运动方式:",
". Правило:": "。规则:",
"Игра придумана!": "游戏想好了!",
"Теперь придумай свою игру. Выбери, что нужно, как двигаться, какое правило и название. А потом обязательно расскажи игру учителю и друзьям.": "现在想出你自己的游戏。选出需要什么、怎样运动、什么规则和名称。然后一定要把游戏告诉老师和朋友。",
"Творческие задачи": "创意任务",
"Подумай, как придумывать и менять игры и как относиться к чужим идеям.": "想一想怎样创造和改变游戏,以及怎样对待别人的想法。",
"Видео: Родина и дружба": "视频:祖国和友谊",
"Что такое патриотизм": "什么是爱国主义",
"Родина": "祖国",
"Любовь к Родине": "对祖国的爱",
"Патриотизм — это любовь и уважение к своей стране, её людям и традициям.": "爱国主义就是热爱和尊重自己的国家、人民和传统。",
"Казахские народные игры, например асық ату и арқан тарту, хранят традиции народа. Играть в них — значит уважать свои корни.": "哈萨克族民间游戏,比如 асық ату 和 арқан тарту,保存着民族的传统。玩这些游戏就是尊重自己的根。",
"Спорт": "体育",
"Гордость за спортсменов": "为运动员自豪",
"Мы гордимся спортсменами, которые защищают честь страны на соревнованиях.": "我们为在比赛中捍卫国家荣誉的运动员感到自豪。",
"Вместе": "一起",
"Играем дружно": "友好地玩",
"Патриот помогает товарищам, играет честно и поддерживает команду.": "爱国者帮助同伴,诚实地玩,并支持队伍。",
"Берегу": "爱护",
"Бережём общее": "爱护公共的东西",
"Школьную площадку и инвентарь нужно беречь: это общее.": "要爱护学校的场地和器材:它们是大家的。",
"Патриотизм — это любовь к своей стране. На физкультуре его можно показать так: играть дружно и честно, помогать товарищам, знать народные игры и беречь общее. Нажимай на картинки.": "爱国主义就是热爱自己的国家。在体育课上可以这样表现:友好而诚实地玩,帮助同伴,了解民间游戏,爱护公共的东西。点点图片吧。",
"Патриот и товарищ": "爱国者和同伴",
"Подумай, как вести себя на физкультуре, чтобы быть настоящим патриотом и хорошим товарищем.": "想一想在体育课上该怎么做,才能成为真正的爱国者和好同伴。",
"Последняя проверка курса: безопасность, движения, цели, роли, творчество и дружба.": "课程的最后检查:安全、动作、目标、角色、创意和友谊。",
"Теперь ты знаешь, как безопасно заниматься, как двигаться в разных местах, как ставить цели и делать планы, какие роли бывают в игре и как играть дружно. Дальше тренируйся в играх. Я буду рядом!": "现在你知道怎样安全地锻炼、怎样在不同的地方运动、怎样定目标和做计划、游戏里有哪些角色以及怎样友好地玩了。接下来在游戏里多练习。我会一直陪着你!",
"Казахские национальные игры": "哈萨克族民族游戏",
"Русское направление 1 класс": "俄语方向一年级",
"Первые слова и фразы: семья, цвета, числа, еда": "最初的单词和句子:家庭、颜色、数字、食物",
"Карандашом рисуют тонкие линии. Лишнюю линию можно стереть ластиком.": "用铅笔画细线。多余的线可以用橡皮擦掉。",
"Фломастер": "马克笔",
"Фломастер рисует яркие и ровные линии.": "马克笔能画出鲜艳而均匀的线条。",
"Мелки": "蜡笔",
"Мелками рисуют широкие яркие линии и закрашивают большие места.": "用蜡笔画宽而鲜艳的线条,给大块地方涂色。",
"Краски": "颜料",
"Красками рисуют картины. Краски смешивают, и получаются новые цвета.": "用颜料画画。把颜料混合起来,会得到新的颜色。",
"Кисть": "画笔",
"Кисточкой берут краску и рисуют. После работы кисть нужно вымыть в воде.": "用画笔蘸颜料来画。画完后要把画笔放在水里洗干净。",
"Пластилин": "橡皮泥",
"Пластилин мягкий. Из него лепят фигурки. Пробовать пластилин на вкус нельзя.": "橡皮泥很软。用它捏小人小动物。橡皮泥不能尝。",
"Цветная бумага": "彩纸",
"Из цветной бумаги вырезают и приклеивают картинки и строят домики.": "用彩纸剪出图案、粘贴画片、搭小房子。",
"Ножницы": "剪刀",
"Ножницами режут бумагу. Работай ножницами осторожно, лучше рядом со взрослым.": "用剪刀剪纸。使用剪刀要小心,最好在大人身边。",
"Рисуют линии": "画线条",
"Рисуют красками": "用颜料画",
"Лепят": "捏塑",
"Вырезают и клеят": "剪和贴",
"Чем рисуют тонкие тёмные линии?": "用什么画细的深色线条?",
"Чем берут краску?": "用什么蘸颜料?",
"Из чего лепят фигурки?": "小人小动物是用什么捏的?",
"Чем режут бумагу?": "用什么剪纸?",
"Что смешивают, чтобы получить новые цвета?": "混合什么能得到新颜色?",
"Графика — это рисунок линиями и штрихами. Его делают карандашом, фломастером или мелками.": "图画是用线条和笔触画的画。用铅笔、马克笔或蜡笔来画。",
"Живопись — это картина, нарисованная красками.": "绘画是用颜料画的画。",
"Скульптура — это объёмная фигурка. Её можно обойти вокруг и рассмотреть со всех сторон. Скульптуры лепят, например, из пластилина или глины.": "雕塑是立体的小人像。可以绕着它走一圈,从各个方向观察。雕塑可以用橡皮泥或黏土来捏。",
"Декоративное искусство": "装饰艺术",
"Декоративное искусство — это красивые узоры и украшения на коврах, посуде и одежде.": "装饰艺术是地毯、餐具和衣服上漂亮的花纹和装饰。",
"Архитектура — это искусство строить красивые и удобные здания.": "建筑是建造漂亮而舒适的房屋的艺术。",
"Дизайн — это когда придумывают красивые и удобные вещи: одежду, посуду, игрушки.": "设计就是想出漂亮又方便的东西:衣服、餐具、玩具。",
