"Прямая линия идёт ровно, без изгибов. Так рисуют дорогу, лучи солнца, забор.": "直线笔直,没有弯曲。用它画路、太阳光线、篱笆。",
"Волнистая": "波浪线",
"Волнистая линия плавно изгибается. Так рисуют волны, ручей, ленту.": "波浪线平缓地弯曲。用它画波浪、小溪、丝带。",
"Ломаная": "折线",
"Ломаная линия поворачивает под острыми углами. Так рисуют молнию и горы с острыми вершинами.": "折线以尖角转折。用它画闪电和有尖顶的山。",
"Спираль": "螺旋线",
"Спираль закручивается по кругу. Так рисуют улитку, завиток, пружинку.": "螺旋线绕着圈卷起来。用它画蜗牛、卷曲、弹簧。",
"Толстая": "粗的",
"Толстая линия получается фломастером или мелком. Она яркая и смелая.": "粗线用马克笔或蜡笔画出来。它鲜艳而大胆。",
"Тонкая": "细的",
"Тонкая линия получается острым карандашом. Она лёгкая и нежная.": "细线用削尖的铅笔画出来。它轻盈而柔和。",
