"Пластилин можно попробовать на вкус": "橡皮泥可以尝",
"Пластилин нельзя брать в рот, он несъедобный.": "橡皮泥不能放进嘴里,它不能吃。",
"Руки после пластилина обязательно моют.": "捏完橡皮泥一定要洗手。",
"Лепить лучше на подложке": "最好在垫板上捏塑",
"Подложка защищает стол от пятен.": "垫板能保护桌子不被弄脏。",
