"Клей нельзя пробовать, он несъедобный.": "胶水不能尝,它不能吃。",
"Кисточку после работы нужно вымыть": "工作完后要把画笔洗干净",
"Кисть моют в воде, чтобы она не засохла.": "画笔要在水里洗,免得变干变硬。",
"На выставке работы смотрят глазами и не трогают руками": "在展览上用眼睛看作品,不用手摸",
"Работы можно испортить, поэтому трогать их нельзя.": "作品会被弄坏,所以不能摸。",
"Можно смеяться над чужим рисунком": "可以嘲笑别人的画",
