"Ковры": "地毯",
"Войлочные ковры": "毡毯",
"Казахские мастерицы делают из войлока красивые ковры с узорами: кошму и сырмак. Тұскиіз — расшитый ковёр на стену юрты.": "哈萨克族女工匠用毛毡做出带花纹的漂亮地毯:毡子和 сырмақ。Тұскиіз 是挂在毡房墙上的绣花地毯。",
"Юрта — это дом кочевников. Она круглая, лёгкая и красиво украшена узорами.": "毡房是游牧民的家。它是圆形的,轻便,用花纹装饰得很漂亮。",
"Домбра и кюй": "冬不拉和库依",
"Домбра — казахский музыкальный инструмент. Кюй — музыка, в которой композитор рассказывает о природе и чувствах.": "冬不拉是哈萨克族的乐器。库依是作曲家讲述自然和感受的音乐。",
"Мир": "世界",
"Искусство мира": "世界的艺术",
"У каждого народа свои картины, скульптуры, здания и узоры. Все они рассказывают о людях и их чувствах.": "每个民族都有自己的画、雕塑、建筑和花纹。它们都在讲述人和他们的感受。",
"Искусство рассказывает о чувствах. В Казахстане его создают веками: войлочные ковры, юрты, музыка домбры. И у других народов мира тоже много красивых произведений. Нажимай на картинки и знакомься.": "艺术讲述感受。在哈萨克斯坦,人们几百年来一直在创造它:毡毯、毡房、冬不拉的音乐。世界上其他民族也有许多美丽的作品。点点图片来认识吧。",
"Что мы знаем об искусстве": "我们对艺术了解什么",
"Ответь на вопросы про искусство нашей страны и про то, что такое произведение искусства.": "回答关于我们国家艺术以及什么是艺术作品的问题。",
"Какое настроение?": "是什么心情?",
"Посмотри на картинку и скажи, какое настроение она передаёт. Помогут цвета: тёплые и яркие радуют, тёмные и холодные грустят или тревожат.": "看看图片,说说它传达了什么心情。颜色会帮助你:暖色和明亮的颜色带来快乐,深色和冷色让人忧伤或不安。",
"Видео: Графика: приёмы": "视频:图画技法",
"Приёмы графики": "图画技法",
"В графике много приёмов: линия, штриховка и точки. Вспомни, для чего они нужны.": "图画里有很多技法:线条、排线和点。想一想它们是做什么用的。",
"Рисуем разными приёмами": "用不同的技法画画",
"Нарисуй линию карандашом": "用铅笔画一条线",
"Выбери «Карандаш» и проведи пальцем или мышкой по листу.": "选“铅笔”,用手指或鼠标在纸上划过。",
"Нарисуй фигуру фломастером и заштрихуй её": "用马克笔画一个图形并画上排线",
"Сначала «Фломастер», потом «Штриховка».": "先选“马克笔”,再选“排线”。",
"Сделай точками небо или землю": "用点画出天空或大地",
"Выбери «Точки» и веди по листу.": "选“点”,在纸上移动。",
"Нарисуй дерево, дом или животное тремя разными приёмами": "用三种不同的技法画一棵树、一座房子或一只动物",
"Попробуй разные инструменты и цвета: художники всегда экспериментируют.": "试试不同的工具和颜色:艺术家总是在尝试。",
"Теперь порисуем разными приёмами. Выполняй задания по порядку. Пробуй карандаш, фломастер, штриховку и точки. Ты можешь стереть всё и начать заново.": "现在用不同的技法画画。按顺序完成任务。试试铅笔、马克笔、排线和点。你可以全部擦掉重新开始。",
