". Покажу:": "。我要展示:",
"Ты рассказал о своей работе!": "你讲述了你的作品!",
"Расскажи о своём рисунке: что ты нарисовал, какое у него настроение и где ты покажешь работу.": "讲讲你的画:你画了什么、它是什么心情、你要在哪里展示作品。",
"Видео: Живопись: мазки и память": "视频:绘画:笔触和记忆",
"Приёмы живописи": "绘画技法",
"В живописи кисть оставляет разные следы: тонкая линия, широкий мазок и тычок. Вспомни, как рисовать по наблюдению и по памяти.": "绘画时画笔会留下不同的痕迹:细线、宽笔触和点按。想一想怎样写生和凭记忆画画。",
"Рисуем красками": "用颜料画画",
"Залей фон широкой кистью светлым цветом": "用宽画笔涂一层浅色背景",
"Выбери «Широкая кисть» и закрась лист светлым цветом.": "选“宽画笔”,用浅色涂满纸。",
"Смешай краски: проведи широкой кистью другого цвета поверх первого": "混合颜料:用另一种颜色的宽画笔涂在第一种上面",
"Жёлтая краска поверх голубой даёт зелёный.": "黄色颜料涂在蓝色上会变成绿色。",
"Нарисуй тонкой кистью ствол или стебель": "用细画笔画树干或茎",
"Выбери «Тонкая кисть» и проведи линию.": "选“细画笔”,画一条线。",
"Поставь мазки-тычки: листья или цветы": "点上点按笔触:叶子或花",
"Выбери «Мазки-тычки» и веди по листу: получится много мазков.": "选“点按笔触”,在纸上移动:会出现很多笔触。",
"Теперь порисуем красками. Залей фон, смешай два цвета, нарисуй стебель и поставь мазки-тычки. Так получается картина: цветочная поляна или дерево с листьями.": "现在用颜料画画。涂背景,混合两种颜色,画茎,再点上点按笔触。这样就画成一幅画:开满花的草地或有叶子的树。",
"Рисуем по памяти": "凭记忆画画",
"Что было в небе?": "天空里有什么?",
"Сколько деревьев было на картинке?": "图上有几棵树?",
"Сколько цветочков было на картинке?": "图上有几朵小花?",
"Что было на небе ночью?": "夜里天上有什么?",
"Какое животное было на картинке?": "图上有哪种动物?",
"Сколько ёлок было на картинке?": "图上有几棵枞树?",
"Художники рисуют не только то, что видят, но и то, что помнят. Рассмотри картинку, запомни, потом спрячь её и ответь на вопросы по памяти. Если ошибёшься, посмотри ещё раз.": "艺术家不仅画看到的东西,也画记得的东西。看看图片,记住,然后把它藏起来,凭记忆回答问题。如果答错了,再看一遍。",
"Как показать картину": "怎样展示画",
"Рамка": "画框",
"Рамка и название": "画框和名称",
"Картину вставляют в рамку или оформляют на плотной бумаге и пишут название и имя автора.": "把画装进画框,或者装裱在厚纸上,并写上名称和作者的名字。",
"Выставка в классе": "教室展览",
"Работы вывешивают на стенде, чтобы все могли посмотреть.": "把作品挂在展板上,让大家都能看到。",
"Рассказ автора": "作者的讲述",
"Автор рассказывает: что нарисовал, какие цвета выбрал и какие чувства передал.": "作者讲述:画了什么、选了什么颜色、表达了什么感受。",
"Электронная презентация": "电子演示",
"Работу можно сфотографировать и показать на экране компьютера.": "可以把作品拍下来,在电脑屏幕上展示。",
"Готовую картину нужно показать. Есть разные способы: рамка, выставка, рассказ автора и показ на экране. Нажимай на картинки.": "做好的画要展示出来。有不同的办法:画框、展览、作者讲述和屏幕展示。点点图片吧。",
"Видео: Лепка: наши фигурки": "视频:捏塑:我们的小人像",
"Виды скульптуры": "雕塑的种类",
"Круглая": "圆雕",
"Её можно обойти кругом и посмотреть со всех сторон.": "可以绕着它走一圈,从各个方向观看。",
"Фигура выступает из плоской основы, как рисунок на монете.": "人像从平的底面凸起,像硬币上的图案。",
"Малая": "小型",
"Малая скульптура": "小型雕塑",
"Маленькие фигурки: игрушки и сувениры. Их лепят из пластилина и глины.": "小小的人像:玩具和纪念品。用橡皮泥和黏土捏成。",
"Памятник": "纪念碑",
"Большая скульптура на площади или в парке в память о людях и событиях.": "立在广场或公园里的大型雕塑,纪念人物和事件。",
"Скульптура бывает разная. Круглая, которую можно обойти кругом, рельеф на плоскости, малая фигурка и большой памятник. Нажимай на картинки.": "雕塑有很多种。可以绕着走一圈的圆雕、平面上的浮雕、小小的人像和大型纪念碑。点点图片吧。",
"Лепим фигурку": "捏小人像",
"Слепи снеговика: три шарика, самый большой внизу": "捏一个雪人:三个小球,最大的在下面",
"Выбери «Шарик» или «Малый шарик» и нажми на лист три раза.": "选“小球”或“小球(小)”,在纸上点三下。",
"Добавь колбаску: это будет рука или хвост": "加一根小香肠:这是手或尾巴",
"Выбери «Колбаска» и нажми рядом с фигуркой.": "选“小香肠”,在小人像旁边点一下。",
"Добавь лепёшку и конус: шапка и нос": "加一个小饼和圆锥:帽子和鼻子",
"Выбери «Лепёшка» и «Конус».": "选“小饼”和“圆锥”。",
"Раскрась фигурку: используй хотя бы три цвета": "给小人像涂色:至少用三种颜色",
"Выбирай цвет, потом нажимай на лист.": "选颜色,再点纸。",
"Теперь слепим фигурку из пластилина, только на экране. Выбери деталь и цвет и нажми на лист. Слепи снеговика, а потом добавь части.": "现在在屏幕上用橡皮泥捏小人像。选零件和颜色,点一下纸。先捏雪人,再加上其他部分。",
"Моя фигурка": "我的小人像",
"Придумай и расскажи о своей фигурке.": "想出你的小人像并讲讲它。",
