". Слепил(а)": "。捏好了",
"Ты придумал фигурку и выразил её настроение!": "你想出了小人像,还表达了它的心情!",
"В лепке тоже можно выражать чувства. Выбери, кого ты слепил, какое у неё настроение и для кого эта фигурка.": "在捏塑里也可以表达感受。选出你捏了谁、它是什么心情、这个小人像是给谁的。",
"Вопросы про лепку": "关于捏塑的问题",
"Ответь на вопросы про виды скульптуры и приёмы лепки.": "回答关于雕塑种类和捏塑技法的问题。",
"Видео: Обобщение и свой узор": "视频:概括和自己的花纹",
"Что такое обобщение": "什么是概括",
"Главное": "主要的东西",
"Обобщить — значит нарисовать предмет просто, главными формами, и убрать лишние мелочи.": "概括就是用主要的形状简单地画物体,去掉多余的细节。",
"Ёлка": "枞树",
"Ёлка из треугольников": "三角形组成的枞树",
"Настоящую ёлку с тысячей иголок упрощают до трёх треугольников.": "有一千根针叶的真枞树被简化成三个三角形。",
"Круглая середина и лепестки-капли.": "圆形的中心和水滴形花瓣。",
"В узорах предметы упрощают. Это называется обобщением. Ёлку рисуют треугольниками, дерево кругом и прямоугольником. Так форму легко повторять. Нажимай на картинки.": "在花纹里要把物体简化。这叫概括。枞树用三角形画,树用圆和长方形画。这样形状容易重复。点点图片吧。",
"Упрощаем формы": "简化形状",
"Подумай, из каких простых форм можно составить предмет.": "想一想一件东西可以由哪些简单的形状组成。",
"Составь свой узор": "设计你自己的花纹",
"Выбери два элемента, цвета и порядок, и получится узор.": "选两个元素、颜色和顺序,就能得到一个花纹。",
"Первый элемент": "第一个元素",
"Второй элемент": "第二个元素",
"Цвет первого": "第一个的颜色",
"Цвет второго": "第二个的颜色",
"Как повторяем": "怎样重复",
"А А Б А А Б": "甲 甲 乙 甲 甲 乙",
"Узор готов! Ты придумал его сам.": "花纹做好了!是你自己想出来的。",
"Теперь придумай свой узор. Выбери два простых элемента, их цвета и порядок повторения. Узор можно потом нарисовать на одежде, ковре или посуде.": "现在想出你自己的花纹。选两个简单的元素、它们的颜色和重复的顺序。花纹以后可以画在衣服、地毯或餐具上。",
"Видео: Дизайн и архитектура": "视频:设计和建筑",
"Дизайнер и архитектор": "设计师和建筑师",
"Дизайнер придумывает, как будет выглядеть вещь: стул, игрушка, упаковка, одежда. Вещь должна быть красивой и удобной.": "设计师想出东西的样子:椅子、玩具、包装、衣服。东西要漂亮又方便。",
"Архитектор придумывает здания: дома, башни, мосты. Здание состоит из простых форм: квадрат, треугольник, арка.": "建筑师设计建筑:房子、塔、桥。建筑由简单的形状组成:正方形、三角形、拱。",
"Конструирование": "构造",
"Это значит собирать вещь из готовых деталей, как из кубиков.": "就是用现成的零件组装东西,像搭积木一样。",
"Макет": "模型",
"Моделирование": "建模",
"Модель, или макет, — это уменьшенный образец здания или вещи.": "模型就是建筑或东西的缩小样品。",
"Дизайнер придумывает вещи, а архитектор здания. Они собирают их из простых деталей и делают макеты. Нажимай на картинки.": "设计师想出东西,建筑师想出建筑。他们用简单的零件组装,并做出模型。点点图片吧。",
"Строим макет дома": "搭一个房子的模型",
"Построй стену дома и крышу": "搭房子的墙和屋顶",
"Нажми «Стена», потом на лист. Затем «Крыша» и нажми над стеной.": "点“墙”,再点纸。然后点“屋顶”,点在墙的上面。",
"Добавь дверь и два окна": "加上门和两扇窗户",
"Выбери «Дверь» и «Окно» и нажми на стену.": "选“门”和“窗户”,点在墙上。",
"Добавь башню или арку: пусть дом станет замком": "加上塔或拱:让房子变成城堡",
"Выбери «Башню» или «Арку».": "选“塔”或“拱”。",
"Построй макет дома из деталей. Сначала стена и крыша, потом дверь и окна. А для красоты добавь башню или арку.": "用零件搭一个房子的模型。先搭墙和屋顶,再加门和窗户。为了好看,可以加一座塔或一个拱。",
"Придумай вещь": "想一件东西",
"Собери вещь из пяти и более простых фигур": "用五个或更多简单的图形拼成一件东西",
"Это может быть игрушка, робот или упаковка. Выбирай фигуры и нажимай на лист.": "可以是玩具、机器人或包装。选图形,点一下纸。",
"Используй три разных цвета": "用三种不同的颜色",
"Меняй цвет перед тем, как поставить фигуру.": "放图形之前先换颜色。",
"Теперь ты дизайнер. Придумай игрушку, робота или упаковку из простых фигур. Используй не меньше пяти фигур и три цвета.": "现在你是设计师了。用简单的图形想出一个玩具、机器人或包装。至少用五个图形和三种颜色。",
