"Последняя проверка курса: материалы, приёмы, цвета, лепка, узор, дизайн и показ работ.": "课程的最后检查:材料、技法、颜色、捏塑、花纹、设计和作品展示。",
"Теперь ты знаешь виды искусства, приёмы графики и живописи, умеешь лепить, придумывать узоры и макеты и показывать свои работы. Рисуй, лепи и показывай свои работы. Я буду рядом!": "现在你知道了艺术的种类、图画和绘画的技法,会捏塑、设计花纹和模型,并展示自己的作品。画画、捏塑,展示你的作品吧。我会一直陪着你!",
