"Сенде неше доп бар?": "Сенде неше доп бар?",
"Сколько у тебя мячей?": "你有几个球?",
"Менде бес доп бар.": "Менде бес доп бар.",
"У меня пять мячей.": "我有五个球。",
"Сенде доп бар ма?": "Сенде доп бар ма?",
