"Здесь сумма": "这里和是",
", а ищем": ",而要找",
"Видео: Что такое сложение?": "视频:什么是加法?",
"Объединяем яблоки": "把苹果合在一起",
"Собираем числа": "拼数",
"Теперь решаешь ты! Нажимай «плюс» и «минус», чтобы собрать нужное число. Красные кружки — первое число, жёлтые — второе. Все вместе они заполняют рамку.": "现在轮到你了!点“加号”和“减号”,凑出需要的数。红色圆圈是第一个数,黄色圆圈是第二个数。它们合在一起正好填满方框。",
"Как называются числа": "数的名称",
"Сколько всего?": "一共多少?",
"Проверим! Сосчитай все яблоки вместе и выбери ответ. Если ошибёшься — я подскажу.": "来检查一下!把所有苹果数一数,选出答案。如果错了,我会提示你。",
"Примеры и названия": "算式和名称",
"Последняя проверка урока: примеры на сложение и названия чисел.": "本课最后的检查:加法算式和数的名称。",
"Видео: Сложение на числовом луче": "视频:数轴上的加法",
"Заяц прыгает по лучу": "兔子在数轴上跳",
"Числовой луч — это линия, на которой числа стоят по порядку. Прибавить — значит прыгнуть вправо. Выбери, где стоит заяц и сколько прыжков сделать, и нажми «Прыгай»!": "数轴是一条线,数按顺序排列在上面。加就是向右跳。选择兔子站在哪里、跳几下,然后点“跳!”",
"Куда он приземлится?": "它会落在哪里?",
"Теперь попробуй угадать! Я скажу, где стоит заяц и сколько прыжков он сделает. Нажми на число, где он окажется.": "现在来猜猜看!我会告诉你兔子站在哪里、要跳几下。点一下它会落到的那个数。",
"Хитрость: досчитываем": "小窍门:接着数",
"Есть хитрость, как складывать быстрее. Начни с большего числа и досчитай меньшее по одному шагу. Нажми «Досчитать» и смотри!": "有个加得更快的小窍门。从大的数开始,再一步一步数上小的数。点“接着数”看看!",
"Проверяем себя": "检查一下自己",
"Проверим, как ты прыгаешь по лучу! Отвечай на вопросы.": "来看看你在数轴上跳得怎么样!回答问题。",
"Видео: Состав числа": "视频:数的组成",
"Домик числа": "数的小房子",
"Все способы": "所有的方法",
"Посмотри, как выглядят все способы разложить число на две части. Выбери число сверху.": "看看把一个数分成两部分的所有方法。在上面选一个数。",
"Сколько не хватает?": "还差多少?",
"Всего кружков столько, сколько написано. Часть уже закрашена. Сколько ещё нужно?": "圆圈一共有写着的那么多。一部分已经涂上颜色。还需要涂多少?",
"Найди лишнее": "找出多余的",
"Последние задания урока. Смотри внимательно: одно из равенств может быть неверным!": "本课最后的题目。仔细看:其中一个等式可能是错的!",
"Видео: Свойства сложения": "视频:加法的性质",
"От перемены мест…": "交换位置……",
"Что будет, если поменять слагаемые местами? Нажми на кнопку и посмотри, как изменится сумма.": "把加数交换位置会怎样?点按钮,看看和会怎么变。",
"Плюс ноль и плюс один": "加零和加一",
"Есть два особых случая. Что будет, если прибавить ноль? А если прибавить один? Переключай вкладки!": "有两种特殊情况。加零会怎样?加一呢?切换标签页看看!",
"Меняем местами": "交换位置",
"Используй правило: от перемены мест слагаемых сумма не меняется.": "用这条规则:交换加数的位置,和不变。",
"Ноль и единица": "零和一",
"Теперь про прибавление нуля и единицы.": "现在来学加零和加一。",
"Видео: Таблица сложения": "视频:加法表",
"Волшебная таблица": "神奇的表格",
"Это таблица сложения. Строка — первое слагаемое, столбец — второе, а в клетке — сумма. Нажимай на клетки и смотри, что подсвечивается.": "这是加法表。行是第一个加数,列是第二个加数,格子里是和。点格子,看看哪里亮起来。",
"Охота за суммой": "寻找和",
"Задание: найди в таблице все клетки с загаданным числом. Какую картинку они образуют? Подсказка: ищи их на одной косой линии.": "任务:在表里找出所有写着指定数的格子。它们组成什么图案?提示:它们在同一条斜线上。",
"Быстрые примеры": "快速算式",
"Решай примеры. Таблица тебе поможет, но лучше вспомнить ответ самостоятельно!": "做算式。表格会帮你,但最好自己想起答案!",
"Теперь ты знаешь, что такое сложение, умеешь прыгать по числовому лучу, раскладывать числа на части, помнишь свойства и таблицу. Дальше — тренировка без конца!": "现在你知道什么是加法,会在数轴上跳,会把数分成几部分,记得性质和加法表。接下来是没完没了的练习!",
