"он отдал": "他给了",
"осталось у Барсика": "巴尔西克还剩",
"Половина от": "一半",
"Отдал": "给了",
"Раздача": "分发",
"На каждой тарелке по": "每个盘子里有",
". Половина от": "。一半是",
"Половина числа — это одна из двух равных частей.": "一个数的一半是两个相等部分中的一个。",
". Нужно хотя бы 4.": "。至少需要 4 个。",
