"Выбрано": "选了",
". Раздели предметы в уме на две одинаковые части и выбери одну из них.": "。在心里把东西分成两个相同的部分,选出其中一部分。",
"Видео: Делим поровну": "视频:平均分",
"Раздаём на две тарелки": "分到两个盘子里",
"Привет! Это Барсик. Когда предметы делят на две одинаковые части, каждая часть называется половиной. Нажимай на предметы, и они по очереди ложатся на две тарелки. Смотри, сколько получится на каждой.": "你好!我是巴尔西克。把东西分成两个相同的部分,每一部分都叫一半。点东西,它们会依次放到两个盘子里。看看每个盘子里有多少。",
"Какая половина?": "哪个是一半?",
"Посмотри на предметы и представь, что их разделили поровну на две части. Сколько будет в одной части?": "看看这些东西,想象把它们平均分成两部分。一部分有多少个?",
"Поровну или нет?": "一样多还是不一样?",
"Половина получается только тогда, когда части одинаковые. Сравни две части и ответь, поделили поровну или нет.": "只有两部分相同,才是一半。比较两部分,回答是不是分得一样多。",
"Видео: Половина числа": "视频:数的一半",
"Половины чисел": "数的一半",
"Половину можно найти у чётных чисел: два, четыре, шесть, восемь, десять. Нажимай на числа и смотри, на какие две равные части они делятся.": "偶数可以求一半:二、四、六、八、十。点这些数,看看它们分成哪两个相等的部分。",
"Выдели половину": "选出一半",
"Теперь твоя очередь. Нажми на столько предметов, сколько составляет половина всех, и нажми «Проверить».": "现在轮到你了。点出和所有东西的一半一样多的东西,然后点“检查”。",
"Найди половину числа": "求数的一半",
"Подбери число, которое вместе с таким же даёт нужное. Например, четыре и четыре — это восемь, значит, половина восьми — четыре.": "选一个数,它和自己相加得到需要的数。比如,四加四是八,所以八的一半是四。",
"Найди целое по половине": "根据一半求整体",
"Теперь наоборот: известна половина, нужно найти всё число. Сложи две одинаковые половины.": "现在反过来:知道了一半,要求出整个数。把两个相同的一半相加。",
"Видео: Половина в задачах": "视频:应用题里的一半",
"Барсик делится": "巴尔西克分东西",
"Барсик делится с другом поровну. Найди половину и ответь на вопрос задачи.": "巴尔西克和朋友平均分。求出一半,回答题目的问题。",
"Последняя проверка курса: половина предметов, половина числа и задачи.": "课程最后的检查:东西的一半、数的一半和应用题。",
"Теперь ты знаешь, что половина — это одна из двух равных частей. Ты умеешь находить половину чисел два, четыре, шесть, восемь и десять. Дальше — тренировка без конца в игре. Я буду рядом!": "现在你知道,一半是两个相等部分中的一个。你会求二、四、六、八和十的一半。接下来在游戏里没完没了地练习。我会一直陪着你!",
