"Видео: Верно или неверно": "视频:对还是错",
"Проверяем по картинке": "看图检查",
"Привет! Это Барсик. Утверждение — это предложение, про которое можно сказать: верно оно или неверно. Посчитай фигуры на картинке и проверь, правду ли говорит утверждение.": "你好!我是巴尔西克。陈述句是可以说它是对的还是错的句子。数一数图上的图形,检查这句话说得对不对。",
"Проверяем числа": "检查数",
"Проверь запись с числами: правильно ли поставлен знак или посчитана сумма. Правильная запись — верная, неправильная — неверная.": "检查带数的算式:符号放得对不对,和算得对不对。写得对的是对的,写得不对的是错的。",
"Проверяем про фигуры": "检查关于图形的说法",
"Теперь утверждения про фигуры. Вспомни, сколько у них сторон и какие они бывают, и скажи, верно ли утверждение.": "现在是关于图形的说法。想想它们有几条边、有哪些种类,说说这个说法对不对。",
"Видео: Признаки и лишнее": "视频:特征和多余的",
"Раскладываем фигуры": "把图形分类",
"У предметов бывают признаки: цвет, форма, размер. По признаку можно разложить предметы на группы. Нажми на фигуру, а потом на коробку, куда она подходит.": "东西有特征:颜色、形状、大小。可以按特征把东西分成组。点图形,再点它该放进的盒子。",
"Сколько с таким признаком?": "有这个特征的有几个?",
"Считай только те фигуры, у которых есть нужный признак: нужный цвет или нужная форма.": "只数有需要特征的图形:需要的颜色或需要的形状。",
"Что лишнее?": "哪个是多余的?",
"Лишний предмет — тот, который не похож на остальные. Найди, чем он отличается: цветом или формой.": "多余的东西是和其他的不一样的那个。找出它哪里不同:颜色还是形状。",
"Видео: Пиктограммы": "视频:象形图",
"Рисуем пиктограмму": "画象形图",
"Пиктограмма — это картинка с данными: один значок значит один предмет. Так удобно считать и сравнивать. Нарисуй пиктограмму по рассказу Барсика.": "象形图是带数据的图画:一个图标代表一件东西。这样数数和比较都很方便。照巴尔西克讲的画一幅象形图。",
"Читаем пиктограмму": "读象形图",
"Смотри на длину строки: чем больше значков, тем больше предметов. Отвечай на вопросы по пиктограмме.": "看行的长度:图标越多,东西越多。根据象形图回答问题。",
"Видео: Ребусы и логические задачи": "视频:图画谜和逻辑题",
"Ребусы с картинками": "图画谜",
"В ребусе одинаковые картинки значат одинаковые числа. Подбери число, чтобы запись стала верной.": "在图画谜里,相同的图画代表相同的数。选一个数,使等式成立。",
"Кто выше?": "谁更高?",
"Выстрой героев по порядку и найди самого высокого или самого низкого. Рассуждай по шагам.": "把角色按顺序排好,找出最高的或最矮的。一步一步地推理。",
"Какого цвета шарик?": "气球是什么颜色?",
"Исключай то, что не подходит. Что останется, то и будет ответом.": "排除不合适的。剩下的就是答案。",
"Видео: Комбинации": "视频:组合",
"Составляем наряды": "搭配衣服",
"Комбинация — это сочетание двух предметов, например, футболки и шапки. Составь все возможные пары и не пропусти ни одной.": "组合是两件东西的搭配,比如T恤和帽子。把所有可能的搭配都组出来,一个也别漏。",
"Сколько вариантов?": "有几种方案?",
"Чтобы не запутаться, составляй пары по порядку: с первым предметом, потом со вторым и так далее.": "为了不搞乱,按顺序组合:先和第一件,再和第二件,依此类推。",
"Последняя проверка курса: верно или неверно, признаки, пиктограммы, ребусы, логика и комбинации.": "课程最后的检查:对错、特征、象形图、图画谜、逻辑和组合。",
"Теперь ты умеешь проверять утверждения, раскладывать предметы по признакам, читать пиктограммы, решать ребусы и составлять комбинации. Дальше — тренировка без конца в игре. Я буду рядом!": "现在你会检查说法、按特征给东西分类、读象形图、解图画谜、组合搭配。接下来在游戏里没完没了地练习。我会一直陪着你!",
