"Сколько воды в ведре": "桶里有多少水",
"Длину измеряют линейкой, массу — весами, а жидкость — литровой банкой.": "长度用尺子量,质量用秤称,液体用升罐量。",
"Длина карандаша": "铅笔的长度",
"Рост ребёнка (длина)": "孩子的身高(长度)",
"Масса арбуза": "西瓜的质量",
"Масса мешка муки": "一袋面粉的质量",
"Сок в пакете": "袋子里的果汁",
"Вода в ведре": "桶里的水",
"Длину считают от нуля до конца предмета.": "长度从零量到东西的末端。",
"Посмотрено длин:": "已看过的长度:",
