". Начало отрезка стоит у нуля. Нажми на число, где он должен закончиться.": "。线段的起点在零。点线段应该结束的那个数。",
"Это начало. Нажми на число, где отрезок заканчивается.": "这是起点。点线段结束的那个数。",
"Верно! Длина отрезка —": "对了!线段的长度是",
"Получился отрезок в": "画出的线段是",
"см, а нужно": "厘米,而需要",
"см. Попробуй другое число.": "厘米。试试别的数。",
"Нажми «+ 1 см» и посчитай, сколько получится.": "点“+ 1 厘米”,数数一共多少。",
"Ещё": "还有",
"см — и будет целый дециметр.": "厘米,就是整整一分米。",
