"Весы ровные:": "天平平衡了:",
"гири по 1 кг — это": "个 1 公斤的砝码就是",
"Гирь слишком много: правая чаша тяжелее. Убери одну.": "砝码太多了:右边的盘子更重。拿掉一个。",
"Гирь пока мало: тяжелее чаша с товаром. Добавь ещё.": "砝码还太少:放货物的盘子更重。再加一个。",
"литр": "升",
"литра": "升",
"литров": "升",
"Верно! В ведре": "对了!桶里有",
"воды.": "水。",
"Налито": "倒了",
"л — это больше, чем нужно. Убери немного воды.": "升——比需要的多。倒出一点水。",
"л. Нужно ещё": "升。还需要",
"Видео: Сантиметр": "视频:厘米",
"Линейка и сантиметры": "尺子和厘米",
"Привет! Это Барсик. Длину измеряют линейкой. Карандаш кладут началом на ноль, а число у его конца показывает длину в сантиметрах. Нажимай на числа и смотри.": "你好!我是巴尔西克。长度用尺子量。把铅笔的一端放在零上,铅笔另一端对着的数就是用厘米表示的长度。点数看看。",
"Измерь сам": "自己量",
"Теперь твоя очередь. Найди, у какого числа заканчивается карандаш, и нажми на это число.": "现在轮到你了。找出铅笔在哪个数结束,然后点这个数。",
"Начерти отрезок": "画线段",
"Линейкой можно не только измерять, но и чертить. Чтобы начертить отрезок нужной длины, начни с нуля и закончи у нужного числа.": "尺子不仅能量,还能画。要画出需要长度的线段,从零开始,画到需要的数结束。",
"Какова длина?": "长度是多少?",
"Посмотри, где заканчивается карандаш, и выбери его длину в сантиметрах.": "看看铅笔在哪里结束,选出它用厘米表示的长度。",
"Длиннее и короче": "更长和更短",
"Сравни два карандаша: чем дальше от нуля заканчивается карандаш, тем он длиннее.": "比较两支铅笔:铅笔结束的位置离零越远,它就越长。",
"Видео: Дециметр": "视频:分米",
"Десять сантиметров": "十厘米",
"Когда сантиметров набирается десять, получается новая единица — дециметр. Нажимай кнопки и смотри, как сантиметры собираются в дециметры.": "够十厘米的时候,就得到一个新的单位——分米。点按钮,看看厘米是怎样凑成分米的。",
"Дециметры и сантиметры": "分米和厘米",
"Помни: один дециметр — это десять сантиметров. Переведи одни единицы в другие.": "记住:一分米是十厘米。把一种单位换成另一种。",
"На сколько длиннее?": "长多少?",
"Чтобы узнать, на сколько один карандаш длиннее другого, вычти меньшую длину из большей.": "要知道一支铅笔比另一支长多少,就用长的减去短的。",
"Видео: Килограмм": "视频:千克",
"Взвешиваем на весах": "在秤上称重",
"Массу измеряют весами в килограммах. На одну чашу кладут товар, на другую — гири. Когда весы ровные, масса товара равна массе гирь. Добавляй гири по 1 килограмму.": "质量用秤以千克为单位来量。一个盘子放货物,另一个盘子放砝码。秤平衡时,货物的质量等于砝码的质量。每次加 1 千克的砝码。",
"Что тяжелее?": "哪个更重?",
"У тяжёлого предмета масса больше, у лёгкого — меньше. Выбери нужный предмет.": "重的东西质量大,轻的东西质量小。选出需要的东西。",
"Задачи про килограммы": "关于千克的应用题",
"Килограммы складывают и вычитают так же, как обычные числа. Не забывай про единицу измерения в ответе.": "千克可以像普通的数一样加减。别忘了在答案里写上单位。",
"Видео: Литр": "视频:升",
"Наливаем литры": "倒升",
"Сколько жидкости помещается в сосуд, измеряют в литрах. Нажимай кнопку, чтобы налить воду литр за литром, и остановись на нужном числе.": "容器里能装多少液体,用升来量。点按钮,一升一升地倒水,在需要的数上停下。",
"Задачи про литры": "关于升的应用题",
"Литры складывают и вычитают так же, как килограммы и сантиметры. Прочитай задачу и выбери ответ.": "升可以像千克和厘米一样加减。读题,选出答案。",
"Видео: Чем и в чём измерять": "视频:用什么量、在什么里量",
"Чем измерить?": "用什么量?",
"Длину измеряют линейкой, массу — весами, а сколько жидкости — литровой банкой. Выбери подходящий прибор.": "长度用尺子量,质量用秤称,液体有多少用升罐量。选出合适的工具。",
"В каких единицах?": "用什么单位?",
"Длину — в сантиметрах, массу — в килограммах, жидкость — в литрах. Выбери верную единицу.": "长度用厘米,质量用千克,液体用升。选出正确的单位。",
"Последняя проверка курса: длина, масса и литры.": "课程最后的检查:长度、质量和升。",
"Теперь ты умеешь измерять длину в сантиметрах и дециметрах, знаешь килограмм и литр и можешь решать задачи про них. Дальше — тренировка без конца в игре. Я буду рядом!": "现在你会用厘米和分米量长度,认识千克和升,还会解关于它们的应用题。接下来在游戏里没完没了地练习。我会一直陪着你!",
