"Он стоит посередине.": "他站在正中间。",
"Слева, справа и между: теперь ты знаешь, как найти место предмета.": "左边、右边和中间:现在你知道怎样找东西的位置了。",
"из 4 нужных.": "个(共 4 个需要的)。",
"на столе": "在桌子上",
"под столом": "在桌子下面",
"над столом": "在桌子上方",
"рядом со столом": "在桌子旁边",
"вне коробки": "在盒子外面",
"Теперь ты знаешь, как сказать, где находится предмет.": "现在你知道怎么说东西在哪里了。",
"Показано положений:": "已看过的位置:",
"из 5 нужных.": "个(共 5 个需要的)。",
"Видео: Слева, справа, впереди, между": "视频:左、右、前、中间",
"Кто где стоит": "谁站在哪里",
"Привет! Это Барсик. Чтобы сказать, где находится предмет, используют слова: слева, справа, между, с краю, посередине. Нажимай на животных!": "你好!我是巴尔西克。要说东西在哪里,就用这些词:左边、右边、中间、边上、正中间。点动物!",
"Слева или справа?": "左边还是右边?",
"Найди животное на картинке и посмотри на соседей. Слева — там, где левая рука, справа — где правая.": "在图上找到这只动物,看看它的邻居。左边就是左手那边,右边是右手那边。",
"Впереди и позади": "前面和后面",
"Когда все идут в одну сторону, впереди — тот, кто идёт первым, а позади — тот, кто идёт следом.": "当大家都往同一个方向走时,前面的是第一个走的,后面的是跟在后面的。",
"Между, с краю, посередине": "中间、边上、正中间",
"Между — это в середине двух предметов. С краю — самый первый или самый последний. Посередине — одинаково далеко от обоих краёв.": "中间就是两个东西当中。边上就是最前面或最后面。正中间就是离两端一样远。",
"Видео: Выше, ниже, над, под": "视频:更高、更低、上、下",
"Где мячик": "球在哪里",
"Нажимай на кнопки, и мячик будет перемещаться. Смотри внимательно: на столе, под столом, над столом, рядом, в коробке, вне коробки.": "点按钮,球就会移动。仔细看:在桌子上、在桌子下、在桌子上方、在旁边、在盒子里、在盒子外。",
"На, под, над, рядом": "上、下、上方、旁边",
"Посмотри, где находится мячик по отношению к столу, и выбери нужное слово.": "看看球相对于桌子在哪里,选出需要的词。",
"Выше и ниже": "更高和更低",
"В этом доме живут звери. Чем выше этаж, тем ближе он к крыше. Найди, кто живёт выше или ниже.": "这座房子里住着小动物。楼层越高,离屋顶越近。找出谁住得更高或更低。",
"Видео: Внутри, снаружи, посередине": "视频:里面、外面、中间",
"Внутри или снаружи?": "里面还是外面?",
"Если предмет окружён со всех сторон, он внутри. Если он за границей, он вне, то есть снаружи.": "如果东西被从各个方向围住,它就在里面。如果在边界之外,它就在外面,也就是在外边。",
"Слева, посередине, справа": "左边、中间、右边",
"Три кружка стоят в ряд. Назови цвет того, который слева, посередине или справа.": "三个圆圈排成一排。说出左边、中间或右边那个圆圈的颜色。",
"Видео: Сравниваем предметы": "视频:比较东西",
"Что больше, выше, шире, толще?": "什么更大、更高、更宽、更厚?",
"Посмотри на два предмета и сравни их. Больше — меньше, выше — ниже, шире — уже, толще — тоньше.": "看看两个东西,比较一下。大——小,高——低,宽——窄,厚——薄。",
"Сравни в жизни": "比较生活中的东西",
"Подумай о настоящих предметах. Жираф выше кошки, а ручей уже реки.": "想想真实的东西。长颈鹿比猫高,小溪比河窄。",
"Видео: Ближе, дальше, числовой луч": "视频:更近、更远、数轴",
"Ближе или дальше?": "更近还是更远?",
"Расстояние — это путь от одного места до другого. Что ближе к школе, до того путь короче.": "距离就是从一个地方到另一个地方的路程。离学校近的,路程就短。",
"Слева и справа на луче": "数轴上的左和右",
"На числовом луче числа растут слева направо. Чем правее число, тем оно больше.": "在数轴上,数从左往右变大。数越靠右,就越大。",
"Последняя проверка курса: слева и справа, выше и ниже, внутри и снаружи, сравнение и числовой луч.": "课程最后的检查:左和右、更高和更低、里面和外面、比较和数轴。",
"Теперь ты можешь рассказать, где находится предмет, и сравнить предметы по размеру. Дальше — тренировка без конца в игре. Я буду рядом!": "现在你能说出东西在哪里,还能按大小比较东西。接下来在游戏里没完没了地练习。我会一直陪着你!",
