"Это вопрос: в нём спрашивают, что нужно найти, и он заканчивается знаком «?».": "这是问题:里面问的是要找什么,并且以“?”结尾。",
"Это условие: в нём сказано, что известно. Искать здесь ничего не нужно.": "这是已知条件:里面说了已知的内容。这里不需要找什么。",
