"Видео: Из чего состоит задача": "视频:题目由什么组成",
"Найди вопрос задачи": "找出题目的问题",
"Привет! Это Барсик. В задаче есть условие, где сказано, что известно, и вопрос, где сказано, что нужно найти. Вопрос заканчивается знаком вопроса. Нажми на предложение, которое является вопросом.": "你好!我是巴尔西克。题目里有已知条件,说的是已知的内容;还有问题,说的是要找的内容。问题以问号结尾。点一下是问题的那句话。",
"Условие или вопрос": "条件还是问题",
"Прочитай предложение и скажи, что это: условие или вопрос. В вопросе спрашивают, а в условии рассказывают, что известно.": "读句子,说说这是什么:条件还是问题。问题是在问,条件是讲已知的内容。",
"Видео: Сумма и остаток": "视频:和与剩余",
"Краткая запись и схема": "简短记录和示意图",
"Чтобы понять задачу, её можно записать коротко и нарисовать схему. Выбирай сумму или остаток, нажимай кнопку и смотри, как строится схема и как находится ответ.": "为了理解题目,可以把它简短地记下来,再画示意图。选和或剩余,点按钮,看看示意图是怎么画的、答案是怎么求出来的。",
"Находим сумму": "求和",
"В этих задачах предметов становится больше или нужно узнать, сколько их вместе. Складывай.": "在这些题里,东西变多了,或者要知道一共有多少。用加法。",
"Находим остаток": "求剩余",
"В этих задачах часть предметов убрали или отдали. Вычти, чтобы узнать, сколько осталось.": "在这些题里,一部分东西被拿走或给出去了。用减法,看看还剩多少。",
"Какое действие выбрать": "选哪种运算",
"Прочитай задачу и выбери действие. Если предметов стало больше или нужно узнать, сколько вместе, то складываем. Если убрали, то вычитаем.": "读题,选运算。如果东西变多了,或者要知道一共有多少,就用加法。如果拿走了,就用减法。",
"Видео: Больше и меньше": "视频:多和少",
"На сколько больше": "多多少",
"Меняй числа кнопками и смотри на предметы. Лишние предметы показывают, на сколько одно число больше другого. Чтобы это узнать, из большего числа вычитают меньшее.": "用按钮改变数,看看东西。多出来的东西表示一个数比另一个数大多少。要知道这个,就用大的数减去小的数。",
"На несколько больше или меньше": "多几个或少几个",
"В этих задачах сказано, на сколько у одного больше или меньше, чем у другого. Если больше, то прибавляем. Если меньше, то вычитаем.": "这些题里说了一个人比另一个人多几个或少几个。如果多,就加;如果少,就减。",
"На сколько больше или меньше": "多多少或少多少",
"Теперь нужно узнать, на сколько одно число больше или меньше другого. Вычти из большего меньшее.": "现在要知道一个数比另一个数大多少或小多少。用大的减去小的。",
