"Предложение на тему": "按主题造句",
"Предложение можно составить из опорных слов. Не забудь большую букву в начале и точку в конце.": "可以用提示词造句。别忘了开头的大写字母和末尾的句号。",
"Поздравление маме": "给妈妈的祝福",
"Собери поздравление: нажимай слова по порядку.": "拼出祝福语:按顺序点词。",
"Сначала обращение: «Дорогая мама».": "先是称呼:“Дорогая мама”。",
"Поздравление готово!": "祝福语拼好了!",
"Дорогая": "Дорогая",
"мама,": "мама,",
"поздравляю": "поздравляю",
"тебя": "тебя",
"праздником!": "праздником!",
"Поздравление — это короткий текст. Собери поздравление маме из слов.": "祝福是一段简短的话。用词拼出给妈妈的祝福。",
"Найди ошибку": "找出错误",
"Проверяй, что написал: большую букву, точку, правильное написание слов. Найди ошибку.": "检查你写的内容:大写字母、句号、词的正确写法。找出错误。",
"Последняя проверка курса: звуки, буквы, слова, предложения и правила письма.": "课程最后的检查:声音、字母、词、句子和书写规则。",
"Теперь ты умеешь слушать и пересказывать, читать по слогам и словами, знаешь мягкий и твёрдый знаки, правила письма и можешь писать предложения. Дальше тренируйся в играх. Я буду рядом!": "现在你会听故事并复述,会按音节和整词阅读,认识软音符号和硬音符号、书写规则,还会写句子。接下来在游戏里练习。我会一直陪着你!",
"Один предмет или много?": "一个还是很多?",
"Найди слово про один предмет": "找出表示一个事物的词",
"один предмет": "один предмет",
