"Собираем множества": "组成集合",
"Привет! Это Барсик. Когда предметы собраны в одну группу по общему признаку, это множество. Например, все фрукты — одно множество, все игрушки — другое. Раскладывай предметы по множествам.": "你好!我是巴尔西克。当东西按共同的特征放进一组时,这就是集合。比如,所有水果是一个集合,所有玩具是另一个集合。把东西分到各个集合里吧。",
