"Сколько элементов?": "有几个元素?",
"Посчитай, сколько предметов в множестве. Это и есть число его элементов.": "数一数集合里有几件东西。这就是它的元素个数。",
"Пустое множество": "空集",
"Бывает и так, что подходящих предметов нет совсем. Множество без элементов называют пустым. В нём ноль элементов.": "有时根本没有合适的东西。没有元素的集合叫做空集。它里面有零个元素。",
"Видео: Объединяем множества": "视频:合并集合",
"Собираем вместе": "放在一起",
"Два множества можно объединить в одно: тогда все их элементы окажутся вместе. Нажми «Объединить» и посмотри, сколько получится.": "两个集合可以合并成一个:这样它们所有的元素就在一起了。点“合并”,看看会有多少。",
"Сколько в объединении?": "并集里有多少?",
"Чтобы узнать, сколько элементов стало в объединении, сложи числа элементов обоих множеств.": "要知道合并后有多少元素,就把两个集合的元素个数相加。",
"Где больше?": "哪边更多?",
"Множества можно сравнивать по числу элементов. Посчитай элементы в каждом и выбери, где больше или меньше.": "集合可以按元素的个数来比较。数一数每个集合里的元素,选出哪个更多或更少。",
"Последняя проверка курса: множества, элементы, пустое множество и объединение.": "课程最后的检查:集合、元素、空集和并集。",
"Теперь ты знаешь, что такое множество и его элементы, умеешь находить пустое множество, объединять множества и сравнивать их. Дальше — тренировка без конца в игре. Я буду рядом!": "现在你知道什么是集合及其元素,会找空集、合并集合并比较它们。接下来在游戏里不停地练习。我会一直陪着你!",
