"У квадрата 4 угла и 4 одинаковые стороны.": "正方形有 4 个角和 4 条相等的边。",
"У прямоугольника 4 угла. Противоположные стороны равны.": "长方形有 4 个角。对边相等。",
"пирамида": "棱锥",
