"луч": "射线",
"угол": "角",
"Точка — самый маленький след карандаша. У неё нет ни длины, ни ширины.": "点是铅笔留下的最小痕迹。它没有长度,也没有宽度。",
"Прямая не изгибается и не заканчивается: у неё нет ни начала, ни конца.": "直线不弯曲,也没有尽头:它没有起点,也没有终点。",
"У луча есть начало, а конца нет: он уходит вдаль.": "射线有起点,没有终点:它向远处延伸。",
"У отрезка есть начало и конец. Его можно измерить линейкой.": "线段有起点和终点。可以用尺子量它。",
"Угол получается, когда из одной точки выходят два луча.": "从一个点引出两条射线,就得到一个角。",
