"Форма предмета «": "东西“",
"Сколько сторон у треугольника?": "三角形有几条边?",
"У треугольника 3 стороны: «три» слышно в названии.": "三角形有 3 条边:名字里就能听出“三”。",
"Сколько сторон у квадрата?": "正方形有几条边?",
"У квадрата 4 стороны, и все они одинаковые.": "正方形有 4 条边,而且都相等。",
"Сколько сторон у прямоугольника?": "长方形有几条边?",
"У прямоугольника 4 стороны: две длинные и две короткие.": "长方形有 4 条边:两条长的和两条短的。",
"Сколько углов у треугольника?": "三角形有几个角?",
"У треугольника 3 угла.": "三角形有 3 个角。",
"Сколько углов у прямоугольника?": "长方形有几个角?",
