"У какой фигуры нет углов?": "哪个图形没有角?",
"Круг круглый, у него нет ни углов, ни сторон.": "圆是圆的,它没有角,也没有边。",
"У какой фигуры 3 угла?": "哪个图形有 3 个角?",
"У треугольника 3 угла и 3 стороны.": "三角形有 3 个角和 3 条边。",
"Сколько сторон у этой фигуры?": "这个图形有几条边?",
"Обведи фигуру пальцем и посчитай стороны. Их": "用手指描一下图形,数一数边。一共有",
"У фигуры": "图形有",
"угла": "个角",
"углов": "个角",
", значит, это": ",所以这是",
"Как называется то, что нарисовано?": "画的东西叫什么?",
"Сколько у этой линии концов (начало тоже считаем концом)?": "这条线有几个端点(起点也算端点)?",
"У луча есть только начало, а конца нет. Значит, конец один.": "射线只有起点,没有终点。所以只有一个端点。",
"У отрезка два конца: начало и конец.": "线段有两个端点:起点和终点。",
"Прямая не заканчивается ни справа, ни слева: концов нет.": "直线向右和向左都没有尽头:没有端点。",
"У какой линии есть начало, но нет конца?": "哪条线有起点,没有终点?",
"У какой линии два конца?": "哪条线有两个端点?",
"У какой линии нет ни начала, ни конца?": "哪条线既没有起点,也没有终点?",
"Что получается, если из одной точки выходят два луча?": "从一个点引出两条射线,会得到什么?",
"Эта линия замкнутая или незамкнутая?": "这条线是封闭的还是不封闭的?",
"замкнутая": "封闭的",
"незамкнутая": "不封闭的",
"Замкнутая линия начинается и заканчивается в одном месте: по ней можно обойти кругом и вернуться. Концов у неё нет.": "封闭的线从同一个地方开始,又在同一个地方结束:可以沿着它绕一圈再回来。它没有端点。",
"У незамкнутой линии есть два свободных конца, она нигде не замыкается.": "不封闭的线有两个自由的端点,它哪里也不闭合。",
"Прямая линия не изгибается и у неё нет концов.": "直线不弯曲,也没有端点。",
"Кривая линия изгибается плавно.": "曲线是平缓地弯曲的。",
"Ломаная состоит из прямых кусочков, соединённых под углом.": "折线由直的小段组成,在拐角处相连。",
"У отрезка есть два конца, они отмечены точками.": "线段有两个端点,用点标出来。",
