"влево. На каком числе он остановится?": "向左。它会停在哪个数上?",
"Считаем назад:": "倒着数:",
"Чему равно": "等于几",
"Числа дружат: из": "数字是朋友:从",
"получаем": "得到",
"Какое сложение проверяет это вычитание?": "哪个加法可以检验这个减法?",
"Чтобы проверить, прибавь разность к вычитаемому:": "检验时,把差加到减数上:",
"— получилось уменьшаемое, значит верно.": "——得到了被减数,说明是对的。",
"Вычесть ноль — ничего не убрать. Число не меняется:": "减零就是什么也没拿走。数不变:",
