"Считая назад, берём число на 1 меньше: после": "倒着数时,取比它小 1 的数:在",
"Считаем по 2. Какое число потерялось?": "按 2 个数一数。丢了哪个数?",
"Каждый раз прибавляем 2:": "每次加 2:",
"В каждой рамке по 2 кружка. Сколько кружков всего? Считай по 2.": "每个框里有 2 个圆圈。一共有多少个圆圈?按 2 个一数。",
"Рамок": "框",
", в каждой по 2. Считаем:": ",每个里有 2 个。数一数:",
