"десятков": "十位",
"Каждая палочка — один десяток. Сколько здесь десятков?": "每根小棒是一个十。这里有几个十?",
"Посчитай палочки по одной: их": "一根一根数小棒:共有",
". Значит, десятков": "。所以十位有",
"В каждой палочке 10 кубиков. Сколько всего кубиков?": "每根小棒里有 10 个小方块。一共有多少个小方块?",
"Считаем десятками:": "按十个一数:",
"Какое число пропущено?": "少了哪个数?",
"Числа идут": "这些数按",
"по десять:": "十个十个地排:",
". Пропущено": "。漏掉的是",
"Считаем десятками. Какое число идёт": "按十个一数。接着是哪个数?",
"десяткам добавляем ещё один десяток:": "十位上再加一个十:",
"Берём на один десяток меньше: перед": "少取一个十:在",
"Какое число называется так?": "哪个数叫这个名字?",
