"Сравни десятки:": "比较十位:",
"Десятков больше у": "十位更多的是",
"Десятков": "十位",
"Один десяток — 10, два десятка — 20, три десятка — 30. Считаем десятками!": "一个十是 10,两个十是 20,三个十是 30。按十个一数!",
", это": ",这是",
"Дальше идёт": "接下来是",
"Это десять десятков. Перед ним стоит": "这是十个十。在它前面的是",
"Перед ним": "在它前面",
", после него": ",在它后面",
"Считаем десятками: 10, 20, 30, ... до ста.": "按十个一数:10、20、30……一直数到一百。",
"Разобрано примеров:": "已学过的例子:",
"дес. =": "个十 =",
"Десятки складывают и вычитают так же, как обычные числа.": "整十数的加减法和一般数的加减法一样。",
"Видео: Палочки-десятки": "视频:十根小棒",
"Один десяток — это 10": "一个十就是 10",
"Привет! Это Барсик. Десять кубиков можно собрать в одну палочку, и это один десяток. Меняй число палочек кнопками и смотри, сколько получается кубиков.": "你好!我是巴尔西克。十个小方块可以拼成一根小棒,这就是一个十。用按钮改变小棒的数量,看看有多少个小方块。",
"Сколько десятков?": "有几个十?",
"Каждая палочка — это один десяток. Посчитай палочки и выбери ответ.": "每根小棒是一个十。数一数小棒,选出答案。",
"Сколько всего кубиков?": "一共有多少个小方块?",
"В каждой палочке десять кубиков. Считай десятками: десять, двадцать, тридцать, и так далее.": "每根小棒里有十个小方块。按十个一数:十、二十、三十,依此类推。",
"Видео: Считаем десятками": "视频:按十个一数",
"Десять, двадцать, тридцать": "十、二十、三十",
"Нажимай на круглые числа от десяти до ста. Я покажу, сколько в каждом десятков и какое число стоит рядом.": "点从十到一百的整十数。我来告诉你每个数里有几个十,旁边是哪个数。",
"Считай десятками вперёд и назад и найди пропущенное число.": "按十个一往前数、往后数,找出漏掉的数。",
"Как называются круглые числа": "整十数怎么称呼",
"У каждого круглого числа своё имя: двадцать, тридцать, сорок. Запомни, как оно называется и как записывается.": "每个整十数都有自己的名字:二十、三十、四十。记住它叫什么、怎么写。",
"Расставь круглые числа от меньшего к большему. Нажимай на числа по очереди: сначала самое маленькое.": "把整十数从小到大排好。依次点数:先点最小的。",
"Видео: Складываем и вычитаем десятки": "视频:整十数的加减法",
"Десятки плюс десятки": "十位加十位",
"Три десятка и два десятка — это пять десятков. А пять десятков — это пятьдесят. Выбирай сложение или вычитание и смотри примеры.": "三个十和两个十是五个十。而五个十就是五十。选加法或减法,看看例子。",
"Складываем десятки": "整十数相加",
"Считай десятками: сколько десятков получилось, столько и десятков в ответе.": "按十个一数:得到几个十,答案里就是几个十。",
"Вычитаем десятки": "整十数相减",
"Из одних десятков вычти другие. Посчитай, сколько десятков осталось.": "从一些十里减去另一些十。数一数还剩几个十。",
"Видео: Сравниваем и повторяем": "视频:比较和复习",
"Сравни десятки: где десятков больше, то число больше. Открытая сторона знака смотрит на большее число.": "比较十位:十位多的数更大。符号张开的一边朝着大的数。",
"Последняя проверка курса: счёт десятками, названия чисел, сложение, вычитание и сравнение десятков.": "课程最后的检查:按十个一数、数的名称、整十数的加减法和比较。",
"Теперь ты умеешь считать десятками до ста, называть и записывать круглые числа, складывать и вычитать десятки и сравнивать их. Дальше — тренировка без конца в игре. Я буду рядом!": "现在你会按十个一数到一百,会称呼和书写整十数,会加减整十数并比较它们。接下来在游戏里不停地练习。我会一直陪着你!",
"часа": "点",
"часов": "点",
"Утром Барсик просыпается, умывается и завтракает.": "早晨,巴尔西克醒来,洗漱,吃早饭。",
"Днём солнце высоко. Барсик учится, играет и обедает.": "白天太阳高高挂着。巴尔西克学习、玩耍、吃午饭。",
"Вечером солнце садится. Барсик ужинает и гуляет.": "傍晚太阳落山。巴尔西克吃晚饭,出去散步。",
"Ночью темно, видны луна и звёзды. Барсик спит.": "夜里很黑,能看见月亮和星星。巴尔西克在睡觉。",
