"Видео: Утро, день, вечер, ночь": "视频:早晨、白天、傍晚、夜晚",
"Из чего состоят сутки": "一昼夜由什么组成",
"Привет! Это Барсик. Сутки делятся на четыре части: утро, день, вечер и ночь. Нажимай на каждую и смотри, чем я занимаюсь.": "你好!我是巴尔西克。一昼夜分成四个时段:早晨、白天、傍晚和夜晚。点每一个,看看我在做什么。",
"Что за чем идёт": "什么在什么后面",
"Части суток всегда идут в одном порядке. Нажми на них по очереди: сначала утро, потом день, вечер и ночь.": "一天的各个时段总是按同一个顺序:点它们,先早晨,再白天、傍晚和夜晚。",
"Прочитай, что делает Барсик и что видно за окном, и выбери, какая это часть суток.": "读一读巴尔西克在做什么、窗外能看到什么,选出这是一天中的哪个时段。",
"Видео: Раньше и позже": "视频:更早和更晚",
"Сначала что-то случается, а потом — следующее. То, что случилось первым, было раньше. То, что потом, — позже. Выбери нужное событие.": "先发生一件事,然后发生下一件。最先发生的更早,后来发生的更晚。选出合适的事件。",
"Вчера, сегодня, завтра": "昨天、今天、明天",
"Вчера — это уже было. Сегодня — это сейчас. Завтра — это ещё будет. Найди в предложении подсказку-слово.": "昨天是已经发生过的。今天是现在。明天是还没发生的。在句子里找出提示词。",
"Видео: Часы показывают час": "视频:钟表显示整点",
"Как устроены часы": "钟表是怎样构成的",
"На часах две стрелки. Короткая красная — часовая, она показывает час. Длинная стрелка в начале каждого часа смотрит на число двенадцать. Минуты ты узнаешь позже, а пока читаем только ровный час. Нажимай на числа.": "钟表有两根指针。短的红色指针是时针,它显示几点。每到整点,长指针都指着数字十二。分钟你以后再学,现在只读整点。点数字看看。",
"Поставь часы": "拨钟表",
"Теперь твоя очередь. Двигай короткую стрелку кнопками, пока часы не покажут нужное время, и нажми «Проверить».": "现在轮到你了。用按钮移动短指针,直到钟表显示所需的时间,然后点“检查”。",
"Сколько часов?": "几点了?",
"Смотри, на какое число показывает короткая красная стрелка. Это и есть час.": "看短的红色指针指着哪个数。那就是几点。",
"Видео: Неделя, месяц, год": "视频:周、月、年",
"Сутки — это один день. Семь дней вместе — это неделя. Расставь дни недели по порядку.": "一昼夜是一天。七天合在一起是一周。把一周的各天按顺序排好。",
"Какой день дальше?": "接下来是哪一天?",
"Дни недели идут по кругу. После воскресенья снова начинается понедельник.": "一周的各天是循环的。星期日之后又从星期一开始。",
"Месяцы и год": "月和年",
"Двенадцать месяцев вместе — это год. Месяцы идут по порядку, а после декабря снова январь.": "十二个月合在一起是一年。月份按顺序排列,十二月之后又是一月。",
"Что длится дольше?": "哪个持续得更久?",
"Минута, час, день, неделя, месяц, год — это единицы времени. Каждая следующая длится дольше предыдущей.": "分钟、小时、天、周、月、年是时间单位。后一个都比前一个持续得更久。",
"Видео: Время в нашем дне": "视频:我们一天中的时间",
"Какие часы нужны?": "需要哪个钟表?",
"Барсик рассказывает, когда он что делает. Найди часы, которые показывают это время.": "巴尔西克讲他什么时候做什么。找出显示这个时间的钟表。",
"Через час и час назад": "1 小时后和 1 小时前",
"Через час — это на один час позже, значит, число увеличивается на один. Час назад — на один раньше, число уменьшается на один.": "1 小时后就是晚一个小时,所以数加一。1 小时前就是早一个小时,数减一。",
"Последняя проверка курса: части суток, раньше и позже, часы, дни недели, месяцы и события дня.": "课程最后的检查:一天的时段、更早和更晚、钟表、星期各天、月份和一天中的事件。",
"Теперь ты знаешь части суток, умеешь сказать, что было раньше и что позже, и читаешь часы с точностью до часа, знаешь дни недели, месяцы и год. Минуты на часах будут впереди. Дальше — тренировка без конца в игре. Я буду рядом!": "现在你知道一天的各个时段,会说什么更早、什么更晚,会读整点,还知道星期的各天、月份和年。钟表上的分钟以后再学。接下来在游戏里不停地练习。我会一直陪着你!",
