"Чёткий взмах — вступление: все начинают вместе.": "干脆的一挥是进入信号:大家一起开始。",
"Дирижёр сжал руки в кулак. Что делаем?": "指挥把手握成了拳头。我们做什么?",
"Заканчиваем пение": "结束歌唱",
"Начинаем петь": "开始唱",
