"Быстрые взмахи — быстрый темп.": "快速的挥动表示快速度。",
"Кто управляет хором и оркестром?": "谁来指挥合唱团和乐队?",
"Дирижёр": "指挥",
"Композитор": "作曲家",
"Слушатель": "听众",
"Хором или оркестром управляет дирижёр.": "合唱团或乐队由指挥来指挥。",
"Как называется часть песни, которая повторяется с одинаковыми словами?": "歌曲中带有相同歌词、会重复的部分叫什么?",
"Припев": "副歌",
"Куплет": "歌节",
"Пауза": "停顿",
"Припев повторяется после каждого куплета.": "副歌在每一段歌节之后重复。",
"Как называется часть песни, в которой слова каждый раз новые?": "歌曲中每次歌词都不一样的部分叫什么?",
"В каждом куплете слова новые.": "每段歌节的歌词都是新的。",
"Песня: куплет, припев, куплет, припев. Сколько раз пели припев?": "歌曲:歌节、副歌、歌节、副歌。副歌唱了几次?",
"Припев пели после первого куплета и после второго: два раза.": "副歌在第一段歌节之后和第二段之后各唱了一次:两次。",
"Какая часть песни повторяется и легко запоминается?": "歌曲的哪个部分会重复,而且容易记住?",
"Припев повторяется, поэтому его легко запомнить.": "副歌会重复,所以很容易记住。",
"Из куплетов и припева": "由歌节和副歌组成",
"Из одних нот": "只由音符组成",
"Из одних пауз": "只由停顿组成",
"Песню составляют куплеты и припев.": "歌曲由歌节和副歌组成。",
"Песня начинается обычно с ...": "歌曲通常从……开始",
"куплета": "歌节",
"паузы": "停顿",
"аплодисментов": "掌声",
"Чаще всего песня начинается с куплета, а потом звучит припев.": "歌曲多半从歌节开始,然后响起副歌。",
"Послушай музыку. Какой это жанр?": "听一听音乐。这是什么体裁?",
"Чёткий, ровный шаг: это марш. Под него шагают.": "整齐、均匀的脚步:这是进行曲。人们随着它迈步。",
"Лёгкая кружащаяся музыка: это танец (вальс). Под неё танцуют.": "轻快旋转的音乐:这是舞曲(华尔兹)。人们随着它跳舞。",
"Плавная напевная мелодия: это песня (колыбельная). Её можно петь.": "舒缓悦耳的旋律:这是歌曲(摇篮曲)。可以唱出来。",
"Под какую музыку шагают строем?": "人们随着什么音乐列队行进?",
"Колыбельная": "摇篮曲",
"Под марш шагают в ногу.": "随着进行曲,大家齐步走。",
"Под какую музыку танцуют?": "人们随着什么音乐跳舞?",
"Песня без мелодии": "没有旋律的歌",
"Танцуют под танцевальную музыку.": "人们随着舞曲跳舞。",
