"Какая нота звучит": "哪个音符在响",
"Первая": "第一个",
"Вторая": "第二个",
"Белая нота — половинная, она звучит дольше (2 доли). Чёрная нота — четвертная, она короче (1 доля).": "白色的音符是二分音符,它响得更久(2 拍)。黑色的音符是四分音符,它更短(1 拍)。",
"Нажимай на ноты и слушай, как они звучат.": "点音符,听一听它们怎么响。",
"Эта нота стоит под нотным станом.": "这个音符在五线谱的下面。",
"Эта нота стоит на первой линейке снизу.": "这个音符在从下数的第一条线上。",
"Эта нота стоит между линейками.": "这个音符在线与线之间。",
"Эта нота стоит на линейке.": "这个音符在线上。",
"Ты познакомился со всеми семью нотами!": "你认识了全部七个音符!",
