"Видео: Безопасная дорога": "视频:安全的道路",
"Привет! Это Барсик. Сегодня поговорим о безопасности. Светофор помогает переходить дорогу. Красный и жёлтый свет — стой. Зелёный — можно идти, но сначала посмотри по сторонам. Нажимай на цвета.": "你好!我是巴尔西克。今天我们来聊聊安全。红绿灯帮助我们过马路。红灯和黄灯——停。绿灯——可以走,但要先看看两边。点颜色。",
"Что делать пешеходу?": "行人该怎么做?",
"Посмотри на светофор и выбери: идти или стоять.": "看看红绿灯,选择:走还是停。",
"На дороге важно соблюдать правила. Решай, как нужно поступать, чтобы остаться в безопасности.": "在路上遵守规则很重要。判断该怎么做才能保证安全。",
