"Три службы помощи": "三种救助服务",
"В беде помогают спасатели. 101 — пожарная служба. 102 — полиция. 103 — скорая помощь. Нажимай на машины и запоминай номера.": "遇到困难时,救援人员会来帮忙。101——消防队。102——警察。103——急救车。点汽车,记住号码。",
