"Теперь попробуй позвонить. Прочитай, что случилось, и набери номер нужной службы. Звонить по этим номерам нужно только когда правда случилась беда.": "现在试着打电话。读一读发生了什么,拨出需要的服务的号码。只有真的出了事才能拨这些号码。",
