"Из чего состоит флаг": "旗由什么组成",
"Флаг — символ нашей страны. На флаге Казахстана голубой фон, золотое солнце, под ним орёл, а у древка узор. Нажимай на части флага.": "旗是我们国家的象征。哈萨克斯坦国旗是天蓝色的底,有金色的太阳,太阳下面有一只鹰,靠旗杆的一边有图案。点旗的各个部分。",
"Что на флаге?": "旗上有什么?",
"Вспомни, что нарисовано на флаге Казахстана, и ответь на вопросы.": "想一想哈萨克斯坦国旗上画着什么,回答问题。",
"Найди наш флаг": "找到我们的旗",
