"Видео: Время года и дни недели": "视频:季节和星期各天",
"Четыре времени года": "四个季节",
"В году четыре времени года: зима, весна, лето и осень. Они идут по кругу. Нажимай на картинки и узнавай, чем они отличаются.": "一年有四个季节:冬、春、夏和秋。它们是循环的。点图片,了解它们有什么不同。",
"Какое время года?": "这是哪个季节?",
"Времена года идут по порядку: зима, весна, лето, осень, и снова зима.": "季节是按顺序排的:冬、春、夏、秋,然后又是冬。",
"В неделе семь дней: понедельник, вторник, среда, четверг, пятница, суббота и воскресенье. Суббота и воскресенье — выходные.": "一周有七天:星期一、星期二、星期三、星期四、星期五、星期六和星期日。星期六和星期日是休息日。",
"Последняя проверка курса: дорога, знаки, службы спасения, флаг, времена года и дни недели.": "课程最后的检查:道路、标志、救援服务、国旗、季节和星期各天。",
"Теперь ты знаешь, как безопасно вести себя на дороге, кого звать на помощь, как выглядит флаг Казахстана, и помнишь порядок времён года и дней недели. Дальше тренируйся в играх. Я буду рядом!": "现在你知道在路上怎样安全行事,遇到困难该叫谁帮忙,哈萨克斯坦国旗是什么样子,还记得季节和星期各天的顺序。接下来在游戏里练习。我会一直陪着你!",
