"Достопримечательности": "名胜",
"Достопримечательности — интересные места: памятники, парки, музеи, красивые здания. Их показывают гостям.": "名胜是有趣的地方:纪念碑、公园、博物馆、漂亮的建筑。人们把它们展示给客人。",
"В любом населённом пункте есть главная улица, важные здания и достопримечательности. Расскажи, что есть там, где живёшь ты.": "每个居民点都有主街、重要建筑和名胜。说一说你住的地方有什么。",
