"Теперь ты знаешь, как безопасно вести себя на дороге и дома, кого звать на помощь, как устроена семья и школа, как называется твой адрес, а ещё знаешь историю нашей земли и символы Казахстана. Дальше тренируйся в играх. Я буду рядом!": "现在你知道在路上和家里怎样安全行事,遇到困难该叫谁帮忙,家庭和学校是怎样的,你的地址叫什么,还了解我们土地的历史和哈萨克斯坦的象征。接下来在游戏里练习。我会一直陪着你!",
