"🏠 Гласные": "🏠 元音",
"воздух идёт свободно, их можно петь": "空气自由地出来,可以唱出来",
"🏡 Согласные": "🏡 辅音",
"воздуху мешают губы, зубы или язык": "嘴唇、牙齿或舌头挡住空气",
"Выбери букву, потом нажми на её домик": "先选字母,再点它的小房子",
