"Над гласной ударного слога ставим знак ударения.": "在重读音节的元音上写重音符号。",
"Подумай ещё": "再想一想",
"💡 Произнеси слово вслух:": "💡 大声说出单词:",
". Какой слог звучит сильнее?": "。哪个音节读得更响?",
"Видео: Звуки и буквы": "视频:声音和字母",
"Из чего состоит слово": "单词由什么组成",
"Привет! Это Барсик. Слова состоят из звуков и букв. Звуки мы слышим и говорим. Буквы мы видим и пишем. Нажимай на картинки и смотри, как слово собирается из звуков и букв.": "你好!我是巴尔西克。单词由声音和字母组成。声音我们听到并说出来。字母我们看见并写出来。点图片,看看单词是怎样由声音和字母组成的。",
"Звуки или буквы?": "声音还是字母?",
"Запомни: звуки слышим и говорим, а буквы видим и пишем. Ответь на вопросы.": "记住:声音听到并说出来,字母看见并写出来。回答问题。",
"Первая буква": "第一个字母",
"Скажи слово про себя и послушай, с какого звука оно начинается. Потом найди нужную букву.": "心里说一说这个词,听一听它是以哪个声音开头的。然后找出需要的字母。",
"Видео: Гласные и согласные": "视频:元音和辅音",
"Два домика": "两个小房子",
"Гласные звуки можно петь: воздух идёт свободно. Это а, о, у, ы, э, я, ё, ю, е, и. А согласным звукам что-то мешает: губы, зубы или язык. Разложи буквы по домикам.": "元音可以唱出来:空气自由地出来。它们是 а、о、у、ы、э、я、ё、ю、е、и。而辅音会被什么挡住:嘴唇、牙齿或舌头。把字母分到小房子里去。",
"Гласная или согласная?": "元音还是辅音?",
"Посмотри на букву и подумай: её можно пропеть без преграды? Тогда она гласная.": "看看字母,想一想:不受阻碍能把它唱出来吗?能,它就是元音。",
"Считаем гласные": "数元音",
"Найди в слове гласные буквы и сосчитай их. Скоро нам это пригодится.": "在单词里找出元音字母并数一数。这个很快就会用上。",
"Видео: Слоги": "视频:音节",
"Хлопаем по слогам": "按音节拍手",
"Слово можно разделить на слоги. В каждом слоге есть одна гласная. Сколько в слове гласных, столько и слогов. Нажми на картинку и хлопай вместе со мной.": "单词可以分成音节。每个音节里有一个元音。单词里有几个元音,就有几个音节。点图片,和我一起拍手。",
"Сколько слогов?": "有几个音节?",
"Прохлопай слово про себя и посчитай хлопки. Или посчитай гласные.": "心里拍一拍手数一数,或者数元音。",
"Раздели на слоги": "分成音节",
"В каждом слоге должна быть гласная. Согласная идёт вместе со своей гласной. Выбери, как правильно разделить слово.": "每个音节里要有元音。辅音和自己的元音在一起。选出怎样正确地给单词分音节。",
"Видео: Слово и предложение": "视频:单词和句子",
"Собери предложение": "组成句子",
"Из слов получаются предложения. Предложение пишут с большой буквы, а в конце ставят знак. Собери предложения из слов по порядку.": "从单词可以组成句子。句子用大写字母写,结尾要加标点。按顺序用单词组成句子。",
"Слово или предложение?": "Слово или предложение?",
"Одно слово называет предмет. Предложение рассказывает о чём-то и состоит из нескольких слов.": "Одно слово называет предмет. Предложение рассказывает о чём-то и состоит из нескольких слов.",
"Знак в конце": "Знак в конце",
"Если рассказываем, ставим точку. Если спрашиваем, ставим вопросительный знак. Если кричим или радуемся, ставим восклицательный знак.": "Если рассказываем, ставим точку. Если спрашиваем, ставим вопросительный знак. Если кричим или радуемся, ставим восклицательный знак.",
"Ударение": "Ударение",
"Видео: Ударение": "Видео: Ударение",
"Ударный слог": "Ударный слог",
"В слове один слог мы произносим громче и дольше. Он называется ударным. Над его гласной ставят знак ударения. Найди ударный слог.": "В слове один слог мы произносим громче и дольше. Он называется ударным. Над его гласной ставят знак ударения. Найди ударный слог.",
"Какой слог ударный?": "Какой слог ударный?",
