"Над какой буквой знак?": "Над какой буквой знак?",
"Знак ударения всегда стоит над гласной ударного слога. Выбери нужную букву.": "Знак ударения всегда стоит над гласной ударного слога. Выбери нужную букву.",
"Последняя проверка курса: звуки, гласные, слоги, предложения и ударение.": "Последняя проверка курса: звуки, гласные, слоги, предложения и ударение.",
"Теперь ты знаешь, чем звуки отличаются от букв, умеешь делить слова на слоги, собирать предложения и находить ударение. Дальше тренируйся в играх. Я буду рядом!": "Теперь ты знаешь, чем звуки отличаются от букв, умеешь делить слова на слоги, собирать предложения и находить ударение. Дальше тренируйся в играх. Я буду рядом!",
"Однажды Барсик пошёл гулять в парк. Там он увидел воробья. Воробей не мог взлететь: у него болело крылышко. Барсик осторожно взял птичку и отнёс её к доктору. Через неделю воробей снова летал над парком.": "Однажды Барсик пошёл гулять в парк. Там он увидел воробья. Воробей не мог взлететь: у него болело крылышко. Барсик осторожно взял птичку и отнёс её к доктору. Через неделю воробей снова летал над парком.",
