"В поделках": "В поделках",
"Национальный узор можно приклеить на открытку, на аппликацию или на рамку. Так твоя работа станет красивой и особенной.": "Национальный узор можно приклеить на открытку, на аппликацию или на рамку. Так твоя работа станет красивой и особенной.",
